/* Autorskie uzupełnienia kart wiedzy; źródła przypisane do parametrów w lab-interpretations.js. */
(()=>{'use strict';
const data={};
function add(id,physiology,within,attention){data[id]={physiology:physiology.split('||'),within,attention};}
add('hct','Hematokryt opisuje udział krwinek czerwonych w objętości krwi, więc zależy zarówno od masy erytrocytów, jak i od objętości osocza. Zmiana ilości wody może zmienić HCT bez zmiany liczby krwinek w całym organizmie. To szczególnie ważne po płynoterapii lub przy odwodnieniu.||W analizatorze HCT jest zwykle obliczany z RBC i MCV. PCV mierzy się po odwirowaniu próbki; te metody mogą różnić się przy nieprawidłowych krwinkach. Niedokrwistość ogranicza zdolność transportu tlenu, ale tolerancja spadku zależy również od szybkości jego narastania i wydolności krążenia.','HCT w zakresie może maskować niedokrwistość u odwodnionego pacjenta. We wczesnym okresie ostrej utraty krwi stężenia mogą jeszcze nie odzwierciedlać pełnego ubytku. Zestaw wynik z trendem i stanem krążenia.','Nie oceniaj regeneracji na podstawie samego HCT. Potrzebne są retikulocyty, rozmaz oraz czas od wystąpienia niedokrwistości.');
add('rbc','Erytrocyty przenoszą hemoglobinę i uczestniczą w dostarczaniu tlenu oraz transporcie dwutlenku węgla. Ich liczba we krwi jest wynikiem równowagi między wytwarzaniem w szpiku, przeżywaniem i usuwaniem z krążenia. Pobudzenie erytropoezy zależy m.in. od odpowiedzi nerek na niedotlenienie.||RBC jest stężeniem komórek, a nie bezpośrednim pomiarem całkowitej masy erytrocytów. Dwie próbki o tej samej liczbie krwinek mogą mieć różny HCT, jeżeli komórki mają różną objętość. Dlatego do opisu niedokrwistości potrzebne są również wskaźniki erytrocytarne.','Liczba RBC w zakresie nie gwarantuje właściwej zawartości hemoglobiny ani prawidłowej wielkości krwinek. Sprawdź HCT, HGB, MCV i rozmaz, szczególnie przy objawach niedokrwistości.','Przy aglutynacji lub hemolizie wynik automatyczny może być mylący. Nie wyciągaj wniosków o produkcji szpikowej wyłącznie z liczby erytrocytów.');
add('hgb','Hemoglobina wiąże tlen w grupach hemowych zawierających żelazo. Jej stężenie pomaga ocenić zdolność krwi do transportu tlenu, ale rzeczywiste dostarczanie tlenu zależy też od utlenowania, przepływu krwi i właściwości samej hemoglobiny.||W rutynowym oznaczeniu krwinki są lizowane, a uwolnioną hemoglobinę mierzy się fotometrycznie. Oznaczana może być więc także hemoglobina obecna poza erytrocytami. Powoduje to ważną różnicę w stosunku do RBC i HCT, które opisują zachowane krwinki.','Stężenie w zakresie nie wyklucza zaburzeń utlenowania ani nieprawidłowych form hemoglobiny. Jeśli HGB nie pasuje do HCT i RBC, najpierw oceń próbkę i metodę pomiaru.','Lipemia może zawyżyć pomiar fotometryczny. Hemoliza może pozostawić względnie wysokie HGB przy spadku RBC i HCT; nie jest to dowód poprawy transportu tlenu.');
add('mcv','MCV opisuje przeciętną objętość erytrocytów. W trakcie dojrzewania komórki zmieniają wielkość, dlatego przewaga młodych krwinek może przesunąć średnią w górę. Niedobór żelaza lub inne zaburzenia erytropoezy mogą sprzyjać powstawaniu mniejszych komórek.||To średnia całej populacji, a nie opis każdej krwinki. Jednoczesna obecność małych i dużych erytrocytów może dać MCV w zakresie. Klasyfikacja mikrocytarna lub makrocytarna porządkuje obraz, lecz nie identyfikuje samodzielnie mechanizmu niedokrwistości.','MCV w zakresie nie wyklucza mieszanych populacji ani regeneracji. Oceń RDW, rozmaz i retikulocyty; normocytarna niedokrwistość może mieć wiele przyczyn.','Makrocytozę potwierdzaj w kontekście czasu przechowywania i aglutynacji. Nie przenoś bezpośrednio ludzkich skojarzeń z niedoborami witamin na psa lub kota.');
add('mch','MCH powstaje przez odniesienie stężenia hemoglobiny do liczby erytrocytów. Opisuje ilość hemoglobiny przypadającą na przeciętną komórkę. Większa krwinka może zawierać więcej hemoglobiny, mimo że jej stężenie wewnątrz komórki pozostaje małe.||MCH silnie zależy od wielkości erytrocytu i wiarygodności obu pomiarów użytych w obliczeniu. Do klasyfikowania wielkości i wysycenia krwinek zwykle większą wartość ma łączna ocena MCV oraz MCHC, uzupełniona rozmazem.','MCH w zakresie nie wyklucza niedokrwistości ani zaburzeń wielkości krwinek. Oceniaj przede wszystkim HCT, MCV, MCHC i morfologię erytrocytów.','Wzrost MCH nie oznacza samodzielnie nadmiaru żelaza. Sprawdź, czy nie wynika ze wzrostu MCV albo zawyżenia HGB.');
add('mchc','MCHC odnosi ilość hemoglobiny do objętości zajmowanej przez krwinki. W odróżnieniu od MCH pomaga opisać jej stężenie w erytrocytach. Młode komórki mogą być większe, a równocześnie słabiej wypełnione hemoglobiną.||Wskaźnik jest obliczany z HGB i HCT, więc dziedziczy ich błędy. Biologiczna możliwość zwiększenia stężenia hemoglobiny w krwince jest ograniczona. Wyraźnie wysokie MCHC jest zatem przede wszystkim sygnałem sprawdzenia jakości próbki i zgodności pomiarów.','MCHC w zakresie nie wyklucza niedokrwistości, regeneracji ani niewielkiej populacji niedobarwliwych krwinek. Zestaw je z MCV, retikulocytami i rozmazem.','Nie rozpoznawaj prawdziwej hiperchromii tylko na podstawie wyniku. Hemoliza, lipemia i aglutynacja mogą zmieniać relację HGB do HCT.');
add('rdw','RDW opisuje zróżnicowanie objętości krwinek, a nie ich średnią wielkość. Przybywanie retikulocytów, pojawienie się mikrocytów albo współistnienie kilku populacji może poszerzać rozkład objętości, zanim MCV wyraźnie się zmieni.||Wskaźnik uzupełnia ocenę anizocytozy w rozmazie. Nie mówi jednak, czy zróżnicowanie wynika z produkcji młodych krwinek, niedoboru substratów czy innego procesu. Jego wartość zależy od równoczesnego obrazu erytrogramu.','RDW w zakresie nie zastępuje oglądania rozmazu. Nie wyklucza niedokrwistości, a nieprawidłowe MCV może występować przy względnie jednorodnej populacji.','Nie traktuj niskiego RDW jako osobnej jednostki chorobowej. Wzrost wymaga identyfikacji rodzaju krwinek, które poszerzają rozkład.');
add('plt','Płytki pochodzą z megakariocytów i uczestniczą w hemostazie pierwotnej. Przywierają w miejscu uszkodzenia naczynia, aktywują się i tworzą czop płytkowy. Ich liczba zależy od produkcji, zużycia, niszczenia i rozmieszczenia w organizmie.||PLT ocenia ilość, a nie pełną sprawność płytek. Krwawienie może wystąpić przy liczbie w zakresie, jeżeli zaburzona jest funkcja płytek lub inne elementy hemostazy. Z kolei agregacja w probówce może dać pozorną małopłytkowość bez rzeczywistego ubytku u pacjenta.','PLT w zakresie nie wyklucza trombocytopatii ani choroby von Willebranda. Przy krwawieniu oceń charakter objawów, leki i pozostałe elementy hemostazy.','U kota szczególnie często najpierw trzeba wykluczyć agregaty. Rozmaz jest istotny również wtedy, gdy analizator zgłasza duże płytki lub problemy z ich rozdzieleniem.');
add('mpv','MPV jest średnią objętością zmierzonych płytek. Rozkład ich wielkości może zmieniać się przy odnowie populacji, ale duże płytki mogą też być cechą osobniczą lub wynikiem zaburzeń powstawania. Nie każda duża płytka jest po prostu młoda.||Ocena ma sens dopiero przy wiarygodnej liczbie PLT. Agregaty, granice rozpoznawania komórek przez analizator i zmiany po pobraniu mogą zmienić średnią lub uniemożliwić jej poprawne wyliczenie.','MPV w zakresie nie rozstrzyga, czy małopłytkowość wynika z niszczenia, zużycia czy mniejszej produkcji. Konieczne są PLT, rozmaz i stan pacjenta.','Nie oceniaj aktywności szpiku na podstawie pojedynczego MPV. Szczególnie przy agregatach wynik może nie reprezentować rzeczywistej populacji.');
add('esr','OB mierzy opadanie erytrocytów w próbce w określonym czasie i warunkach. Proces zależy od oddziaływania komórek z białkami osocza oraz od liczby i właściwości krwinek. Zmiana nie jest bezpośrednim pomiarem konkretnego mediatora zapalenia.||Przy zapaleniu zmiana składu białek może przyspieszać sedymentację, lecz niedokrwistość i nieprawidłowa morfologia erytrocytów również modyfikują wynik. Przydatność należy oceniać dla użytej metody i gatunku, bez przenoszenia ludzkich zakresów.','OB w zakresie nie wyklucza zapalenia. Oceniaj objawy, morfologię i odpowiednie dla gatunku białka ostrej fazy, zamiast opierać wniosek na samym opadaniu.','Nieswoisty wzrost nie lokalizuje procesu. Wyniki z różnych systemów pomiarowych nie muszą być bezpośrednio porównywalne.');
add('wbc','WBC sumuje różne populacje leukocytów o odmiennych zadaniach. Liczba we krwi odzwierciedla produkcję szpikową, uwalnianie z magazynów, przemieszczanie między pulą krążącą i przyścienną oraz przechodzenie do tkanek.||Dlatego wzrost nie musi oznaczać zwiększonej produkcji, a spadek nie musi oznaczać niewydolności szpiku. Ten sam WBC może ukrywać neutrofilię z limfopenią lub inne przeciwstawne zmiany. Różnicowanie leukocytów i ich morfologia są niezbędną częścią interpretacji.','Prawidłowe WBC nie wyklucza zapalenia ani nieprawidłowej jednej populacji. Oceń bezwzględny rozdział leukocytów, lewy zwrot, zmiany toksyczne i ewentualne nietypowe komórki.','Nie przypisuj każdej leukocytozy infekcji bakteryjnej. Pobudzenie, glikokortykosteroidy i choroby rozrostowe mogą tworzyć odmienne wzorce.');
add('bands','Pałeczki są niedojrzałymi neutrofilami, uwalnianymi ze szpiku przed pełną segmentacją jądra. Wzrost ich liczby, czyli lewy zwrot, informuje o relacji między zapotrzebowaniem tkanek a dostępną pulą dojrzałych komórek.||Znaczenie zależy od równoczesnej liczby neutrofili segmentowanych oraz obecności wcześniejszych form i zmian toksycznych. Nasilona niedojrzałość przy małej puli dojrzałych komórek ma inne znaczenie niż niewielki lewy zwrot przy neutrofilii.','Brak wzrostu pałeczek nie wyklucza zapalenia. Odpowiedź zależy od czasu, intensywności procesu i rezerwy szpiku, a rozróżnianie form w rozmazie ma ograniczenia.','Sam procent pałeczek może wprowadzać w błąd. Uwzględnij liczbę bezwzględną i całość obrazu neutrofilowego.');
add('neut','Neutrofile stanowią ważną część szybkiej odpowiedzi zapalnej i fagocytują drobnoustroje oraz uszkodzony materiał. Po dojrzewaniu w szpiku trafiają do krwi, a następnie do tkanek. Krew jest etapem transportu, nie jedynym miejscem ich działania.||Na wynik wpływa uwalnianie ze szpiku, demarginalizacja oraz tempo opuszczania naczyń. Krótkotrwałe pobudzenie i glikokortykosteroidy zmieniają rozmieszczenie komórek inaczej niż silne zapalenie z nasilonym zużyciem.','Liczba segmentowanych neutrofili w zakresie nie wyklucza zapalenia. Sprawdź pałeczki, zmiany toksyczne i trend; liczba komórek oraz ich morfologia niosą różne informacje.','Neutropenia z objawami ogólnymi może oznaczać duże zapotrzebowanie tkankowe lub zahamowanie produkcji. Nie zakładaj, że brak neutrofilii oznacza łagodny proces.');
add('eos','Eozynofile uczestniczą w określonych odpowiedziach na pasożyty, reakcjach nadwrażliwości i regulacji zapalenia. Większość funkcji wykonują w tkankach, zwłaszcza na powierzchniach kontaktu ze środowiskiem. Liczba we krwi nie odzwierciedla bezpośrednio całej puli tkankowej.||Ich napływ i przeżywanie są regulowane przez mediatory zapalne. Glikokortykosteroidy mogą obniżać liczbę krążących komórek. Różne choroby o podobnym wzroście eozynofili wymagają odróżnienia na podstawie lokalizacji objawów i wywiadu.','Eozynofile w zakresie nie wykluczają pasożytów ani choroby eozynofilowej tkanek. Brak eozynofilii nie może zastąpić odpowiednich badań parazytologicznych lub oceny narządu.','Eozynofilia nie jest synonimem alergii. Zestaw ją z objawami skórnymi, oddechowymi i pokarmowymi, ekspozycją oraz innymi liniami komórkowymi.');
add('baso','Bazofile są rzadką populacją granulocytów. Ich ziarnistości zawierają mediatory uczestniczące w odpowiedzi zapalnej i reakcjach nadwrażliwości. Mogą towarzyszyć odpowiedzi eozynofilowej, lecz mechanizmy obu zmian nie są identyczne.||Przy małej liczbie komórek pojedyncze różnice w rozdziale mają duży wpływ na procent. Potwierdzenie w rozmazie jest szczególnie ważne, gdy automatyczna klasyfikacja nie pasuje do pozostałych danych.','Brak bazofili w rozdziale może być fizjologiczny. Nie świadczy o niedoborze odporności i nie wyklucza reakcji nadwrażliwości ani pasożytów.','Nie nadawaj małemu wzrostowi procentowemu znaczenia bez liczby bezwzględnej i potwierdzenia identyfikacji komórek.');
add('lymph','Limfocyty obejmują komórki o różnych funkcjach, m.in. odpowiedź komórkową, wytwarzanie przeciwciał i cytotoksyczność. Wynik rutynowy sumuje te populacje i nie określa ich swoistości ani funkcjonalnej sprawności.||Komórki stale przemieszczają się między krwią, narządami limfatycznymi i tkankami. Pobudzenie adrenergiczne może przejściowo zwiększać liczbę, a glikokortykosteroidy sprzyjać limfopenii. Utrwalona limfocytoza z nietypową morfologią wymaga innej oceny niż krótkotrwała reakcja pobudzenia.','Liczba limfocytów w zakresie nie jest testem pełnej sprawności odporności. Niewielka populacja nieprawidłowych komórek może wymagać oceny rozmazu mimo poprawnej sumy.','U kota pobudzenie podczas pobrania może wyraźnie wpływać na wynik. Odróżniaj limfocyty reaktywne od podejrzanych o rozrost, uwzględniając utrzymywanie się zmiany.');
add('mono','Monocyty powstają w szpiku i po przejściu do tkanek mogą różnicować się w makrofagi. Uczestniczą w fagocytozie, usuwaniu uszkodzonych komórek i regulacji odpowiedzi zapalnej oraz naprawy tkanek.||Ich liczba może wzrastać przy zwiększonym zapotrzebowaniu na fagocyty. U psa glikokortykosteroidy także mogą wywołać monocytozę. Wynik sam nie określa, czy proces jest ostry, przewlekły, zakaźny lub jałowy.','Monocyty w zakresie nie wykluczają zapalenia ani aktywności makrofagów w tkankach. Izolowana niewielka monocytopenia zwykle ma ograniczoną wartość diagnostyczną.','Nie utożsamiaj monocytozy automatycznie z przewlekłą infekcją. Oceniaj neutrofile, obraz tkanek, leki oraz utrzymywanie się zmiany.');
add('anisocytosis','Anizocytoza oznacza zróżnicowanie wielkości erytrocytów oglądanych w rozmazie. Może powstać, gdy do krwi dołącza populacja młodych większych komórek lub pojawiają się mniejsze erytrocyty w zaburzonej erytropoezie.||Opis morfologiczny uzupełnia MCV i RDW. Rozmaz pokazuje średnicę i kształt na szkiełku, a analizator objętość komórek; nie są to dokładnie te same pomiary. Istotne jest, jakie komórki tworzą różnorodność i czy występuje niedokrwistość.','Brak wyraźnej anizocytozy nie wyklucza niedokrwistości ani niewielkich zmian populacji. Zestaw ocenę rozmazu z MCV, RDW i retikulocytami.','Nie opisuj anizocytozy jako rozpoznania etiologicznego. Regenerację trzeba potwierdzić, a nie wnioskować o niej wyłącznie z różnicy wielkości krwinek.');
add('polychromasia','Polichromazja jest niebieskawym zabarwieniem młodych erytrocytów zawierających pozostałości RNA w standardowo barwionym rozmazie. Odzwierciedla obecność części retikulocytów i może wspierać ocenę odpowiedzi szpiku.||Nie wszystkie retikulocyty są widoczne jako polichromatofile. U kota formy punkcikowate mogą utrzymywać się dłużej i nie reprezentują bieżącej regeneracji tak dobrze jak agregatowe. Dlatego ocena barwy nie zastępuje oznaczenia właściwej populacji retikulocytów.','Brak polichromazji nie przesądza o nieregeneratywności: odpowiedź może być jeszcze zbyt wczesna, mała albo niedostatecznie widoczna w tej metodzie.','Oceniaj polichromazję względem stopnia niedokrwistości. Ta sama liczba młodych komórek może być wystarczająca w łagodnej i nieadekwatna w ciężkiej niedokrwistości.');
add('poikilocytosis','Poikilocytoza oznacza zróżnicowanie kształtów erytrocytów. Poszczególne formy mogą powstawać wskutek fragmentacji, zmian błony, stresu oksydacyjnego lub zaburzonego dojrzewania. Sam zbiorczy termin nie opisuje jednego mechanizmu.||Wartość diagnostyczną wnosi identyfikacja konkretnych postaci i ich nasilenia. Komórki na zbyt grubym lub cienkim obszarze rozmazu oraz artefakty suszenia mogą naśladować zmiany patologiczne, dlatego jakość preparatu jest kluczowa.','Brak nasilonej poikilocytozy nie wyklucza hemolizy ani choroby szpiku. Nieliczne charakterystyczne komórki mogą mieć większe znaczenie niż ogólny stopień zmienności kształtu.','W opisie potrzebne są nazwy dominujących form, nie tylko plusy. Nie każdy nieprawidłowy kształt oznacza tę samą chorobę u psa i kota.');
add('nrbc','Erytroblasty są jądrzastymi prekursorami erytrocytów. Zwykle dojrzewają w szpiku i tracą jądro przed przejściem do krwi. Ich obecność w krążeniu może towarzyszyć regeneracji, ale także zaburzeniom bariery szpikowej lub innym procesom.||Nie są równoznaczne z retikulocytami. Niektóre analizatory mogą zaliczać je do komórek jądrzastych i pozornie zawyżać WBC. Raport powinien wskazywać, czy liczba leukocytów została odpowiednio skorygowana.','Brak erytroblastów nie wyklucza choroby szpiku ani niedokrwistości regeneratywnej. Niewielkie liczby wymagają odniesienia do gatunku, wieku i całego rozmazu.','Erytroblastoza nie dowodzi regeneracji bez odpowiednich retikulocytów. Sprawdź również poprawność WBC i obecność innych nieprawidłowych komórek.');
add('retic','Retikulocyty są młodymi erytrocytami po utracie jądra, nadal zawierającymi RNA. Ich wzrost pokazuje zwiększony dopływ komórek ze szpiku, ale odpowiedź na utratę lub niszczenie krwinek wymaga czasu.||Liczba bezwzględna lepiej niż sam procent opisuje wielkość odpowiedzi, ponieważ procent zależy od liczby pozostałych erytrocytów. U kotów bieżącą regenerację ocenia się przede wszystkim z form agregatowych; punkcikowate mogą odzwierciedlać wcześniejszą odpowiedź.','U anemicznego pacjenta wynik w zakresie zdrowych zwierząt może oznaczać odpowiedź nieadekwatną. Interpretuj liczbę względem głębokości niedokrwistości i czasu jej trwania.','W pierwszych dniach niedokrwistości brak wyraźnego wzrostu nie zawsze oznacza trwały brak zdolności regeneracyjnej. Porównuj kolejne oznaczenia z HCT.');
add('pt','PT mierzy czas tworzenia skrzepu po dodaniu odpowiednich odczynników do osocza. Ocenia głównie szlak zewnątrzpochodny i wspólny, obejmujący działanie kilku czynników krzepnięcia. Nie mierzy bezpośrednio liczby ani funkcji płytek.||Czas wydłuża się, gdy aktywność istotnych czynników staje się zbyt mała lub obecne są inhibitory. Zależność wyniku od odczynnika i jakości osocza oznacza, że niewielkich różnic między laboratoriami nie należy interpretować bez lokalnego zakresu.','PT w zakresie nie wyklucza trombocytopatii, choroby von Willebranda ani każdego niedoboru czynników. Oceniaj razem z APTT i charakterem krwawienia.','Przy nieprawidłowym napełnieniu probówki cytrynianowej lub bardzo wysokim HCT wynik może być niewiarygodny. Skrócony PT nie jest prostym testem nadkrzepliwości.');
add('aptt','APTT jest osoczowym testem szlaku wewnątrzpochodnego i wspólnego krzepnięcia. Oznacza czas powstawania skrzepu po aktywacji układu w warunkach laboratoryjnych, a nie całkowitą sprawność hemostazy w żywym organizmie.||Na wydłużenie wpływają niedobory czynników i inhibitory, w tym heparyna. Nie każdy niedobór powodujący długi APTT wiąże się z krwawieniem; znaczenie zależy od konkretnego czynnika. Dlatego wynik wymaga konfrontacji z PT, płytkami i objawami.','APTT w zakresie nie wyklucza zaburzeń płytek ani wszystkich łagodnych niedoborów czynników. Krwawienie z prawidłowymi czasami nadal wymaga wyjaśnienia.','Unikaj interpretacji próbki zanieczyszczonej heparyną z cewnika. Krótki czas nie potwierdza samodzielnie nadkrzepliwości.');
add('fibrinogen','Fibrynogen jest białkiem osocza syntetyzowanym w wątrobie i substratem do powstawania fibryny. Łączy rolę w hemostazie z odpowiedzią ostrej fazy: jego produkcja może rosnąć podczas zapalenia, a zużycie zwiększać się przy tworzeniu skrzepów.||Stężenie jest wypadkową syntezy, zużycia i utraty. Równoczesne zapalenie może częściowo maskować zużycie, więc wynik nie zawsze spada mimo istotnego procesu. Różne metody pomiaru nie oceniają dokładnie tego samego.','Fibrynogen w zakresie nie wyklucza zapalenia ani zużywania czynników. Oceniaj trend, PT, APTT, PLT i inne dane dotyczące krzepnięcia.','Rozróżniaj oznaczenie czynnościowe od oszacowania metodą wytrącania. Sam fibrynogen nie potwierdza ani nie wyklucza DIC.');
add('ast','AST uczestniczy w przemianach aminokwasów i występuje w hepatocytach, mięśniach oraz innych komórkach. Aktywność we krwi wzrasta wskutek uwalniania enzymu z komórek; nie jest to bezpośrednia ocena wydolności narządu.||Ponieważ źródło nie jest swoiste, równoczesna ocena CK pomaga rozważyć udział mięśni, a ALT i inne parametry obraz wątrobowy. Znaczenie ma czas od uszkodzenia: różne enzymy mają różną dynamikę wzrostu i spadku.','AST w zakresie nie wyklucza choroby wątroby ani mięśni. Brak aktywnego uwalniania enzymu w chwili pobrania nie oznacza prawidłowej struktury i funkcji narządu.','Przy wzroście AST nie pomijaj mięśni i hemolizy. Samo AST nie pozwala odróżnić martwicy wątroby od innych źródeł.');
add('alt','ALT jest enzymem przemian aminokwasów zlokalizowanym głównie w cytoplazmie hepatocytów. U psów i kotów służy jako marker uszkodzenia komórek wątroby: zwiększenie przepuszczalności błon lub śmierć komórek pozwalają enzymowi przejść do krwi.||Aktywność zależy od nasilenia uwalniania, liczby komórek oraz eliminacji enzymu. Wysoki wynik nie określa sam przyczyny, rozległości trwałego uszkodzenia ani rezerwy czynnościowej wątroby. Spadek w czasie wymaga odniesienia do stanu pacjenta i innych parametrów.','ALT w zakresie nie wyklucza przewlekłej choroby, zmian ogniskowych ani niewydolności wątroby. Ocena funkcji wymaga innych danych niż sama aktywność enzymu.','Nie utożsamiaj wysokości ALT z rokowaniem. Odróżniaj aktywne uszkodzenie od zaburzeń odpływu żółci i od upośledzenia syntezy.');
add('alp','ALP obejmuje izoenzymy pochodzące z różnych tkanek, m.in. układu wątrobowo-żółciowego i kości. Wzrost może wynikać z indukcji syntezy, a nie tylko z uwalniania enzymu z uszkodzonych komórek. Dlatego mechanizm różni się od typowych enzymów wyciekowych.||U psa glikokortykosteroidy mogą silnie indukować ALP; u młodych zwierząt znaczenie ma wzrost kości. U kota wzrost wymaga szczególnie uważnej oceny hepatobiliarnej. Porównywanie gatunków bez uwzględnienia tych różnic prowadzi do błędnych wniosków.','ALP w zakresie nie wyklucza choroby wątroby ani dróg żółciowych. Parametr nie jest testem całkowitej zdolności wątroby do metabolizowania i syntezy.','Przed przypisaniem wyniku cholestazie sprawdź wiek i leki. ALP oraz GGT mogą tworzyć różne proporcje zależnie od procesu, szczególnie u kotów.');
add('ggt','GGT jest enzymem związanym z błonami komórkowymi, uczestniczącym m.in. w metabolizmie glutationu. W surowicy jego głównym źródłem jest układ wątrobowo-żółciowy, zwłaszcza nabłonek dróg żółciowych. Duża zawartość w innej tkance nie oznacza, że jej uszkodzenie musi zwiększyć GGT we krwi.||Wzrost może towarzyszyć cholestazie i zmianom nabłonka przewodów. Ocena łącznie z ALP, bilirubiną i obrazowaniem pomaga rozróżnić wzorzec hepatobiliarny od samego uszkodzenia hepatocytów.','GGT w zakresie nie wyklucza choroby wątroby ani każdego rodzaju cholestazy. Interpretuj je z ALP i bilirubiną, a nie jako samodzielny test drożności dróg żółciowych.','Nie oceniaj całej funkcji wątroby z GGT. Rozbieżność ALP i GGT może być istotniejsza niż pojedyncze przekroczenie granicy.');
add('gldh','GLDH jest enzymem mitochondrialnym przemian glutaminianu. W diagnostyce wykorzystuje się jego uwalnianie z uszkodzonych hepatocytów. Lokalizacja mitochondrialna różni go od enzymów obecnych głównie w cytoplazmie.||Aktywność odzwierciedla uszkodzenie komórek, a nie bezpośrednio zdolność wątroby do syntezy białek czy metabolizowania związków. Przydatność i dostępność testu zależą od gatunku oraz laboratorium; u psów i kotów wynik uzupełnia obraz oceniany z innymi enzymami.','GLDH w zakresie nie wyklucza zmian ogniskowych ani zaburzeń czynnościowych. Brak wyraźnego uwalniania enzymu nie jest dowodem braku choroby.','Nie wyznaczaj rozległości martwicy ani rokowania z samej aktywności GLDH. Zestaw ją z ALT, AST i parametrami funkcjonalnymi.');
add('bilirubin','Bilirubina powstaje podczas rozkładu hemu, w dużej części z erytrocytów. Frakcja niesprzężona jest transportowana z albuminą do wątroby, gdzie zachodzą wychwyt i sprzęganie, a następnie wydzielanie do żółci.||Stężenie może wzrosnąć wskutek zwiększonej produkcji przy hemolizie, zaburzonego przetwarzania w hepatocytach lub utrudnionego wydalania żółci. Te mechanizmy mogą współistnieć. Żółtaczka jest objawem nagromadzenia barwnika, a nie nazwą jednej choroby.','Bilirubina w zakresie nie wyklucza choroby wątroby, łagodnej hemolizy ani wczesnej cholestazy. Oceń erytrogram i enzymy, jeżeli obraz kliniczny budzi podejrzenia.','Przy wzroście rozważ także przyczynę przedwątrobową. Same frakcje nie zastępują oceny hemolizy, miąższu i odpływu żółci.');
add('urea','Mocznik powstaje w wątrobie podczas przetwarzania azotu pochodzącego z metabolizmu aminokwasów. Jest wydalany głównie przez nerki, ale jego stężenie zależy także od podaży białka, katabolizmu i zdolności wątroby do syntezy.||Po filtracji część mocznika może być zwrotnie wchłaniana; wpływa na to przepływ moczu. Dlatego wzrost nie musi oznaczać pierwotnej choroby nerek, a rozbieżność z kreatyniną może wskazywać na wpływ produkcji lub perfuzji. Krwawienie do przewodu pokarmowego zwiększa dopływ strawionego białka.','Mocznik w zakresie nie wyklucza wczesnej choroby nerek ani sytuacji, w której mniejsza produkcja maskuje upośledzenie wydalania. Oceń kreatyninę, SDMA i mocz.','Mocznik i BUN opisują różne wielkości i mają inne przeliczniki. Nie porównuj liczb bez sprawdzenia nazwy oznaczenia i jednostki.');
add('sdma','SDMA powstaje podczas rozpadu białek zawierających metylowaną argininę. Jest usuwana głównie przez nerki, dlatego wzrost stężenia może sygnalizować spadek filtracji kłębuszkowej. Jej związek z masą mięśniową jest mniejszy niż kreatyniny.||Marker jest szczególnie przydatny jako uzupełnienie oceny pacjenta z małym umięśnieniem lub przy obserwacji trendu. Nie lokalizuje uszkodzenia i nie odróżnia sam przyczyn przednerkowych, nerkowych i pozanerkowych ani procesu ostrego od przewlekłego.','SDMA w zakresie nie wyklucza każdej choroby nerek, zwłaszcza zmian strukturalnych lub białkomoczu. Interpretuj z moczem, kreatyniną i historią pacjenta.','Pojedynczego niewielkiego wzrostu nie traktuj jako gotowego rozpoznania PChN. Potwierdź utrzymywanie się zmiany i oceń stan nawodnienia oraz pozostałe wyniki.');
add('total-protein','Białko całkowite obejmuje albuminę i wiele frakcji globulin. Pomiar pokazuje ich łączne stężenie, które zależy od syntezy, utraty, rozpadu i objętości wody w osoczu. Wzrost może więc oznaczać zagęszczenie, a nie nadprodukcję.||Przeciwstawne zmiany albuminy i globulin mogą się wzajemnie maskować. Białko w surowicy i osoczu nie jest dokładnie tym samym oznaczeniem, ponieważ osocze zawiera m.in. fibrynogen; oszacowanie refraktometryczne również ma własne ograniczenia.','Suma w zakresie może ukrywać hipoalbuminemię z hiperglobulinemią. Sprawdź frakcje i stosunek A/G, szczególnie przy przewlekłym zapaleniu lub utracie białka.','Nie utożsamiaj białka całkowitego ze stanem odżywienia. Nawodnienie i proporcje frakcji często zmieniają interpretację bardziej niż sama suma.');
add('albumin','Albumina jest syntetyzowana w wątrobie, współtworzy ciśnienie onkotyczne i przenosi wiele substancji, m.in. leki, bilirubinę i część wapnia. Jej stężenie zależy od syntezy, utraty przez nerki lub jelita, rozmieszczenia i nawodnienia.||Przy zapaleniu stężenie może maleć jako element odpowiedzi ustrojowej. Spadek może sprzyjać obrzękom, ale ich wystąpienie zależy również od przepuszczalności naczyń i innych mechanizmów. Niższy wapń całkowity przy małej albuminie nie musi oznaczać małego wapnia zjonizowanego.','Albumina w zakresie nie wyklucza początkowej utraty białka ani choroby wątroby. Odwodnienie może maskować obniżenie, a dynamika zmian może być opóźniona.','Nie przypisuj hipoalbuminemii automatycznie wątrobie. Oceń mocz i UPC, przewód pokarmowy, stan zapalny oraz ewentualne straty do jam ciała.');
add('globulin','Globuliny obejmują białka transportowe, białka ostrej fazy i immunoglobuliny. W rutynowym profilu ich ilość często oblicza się przez odjęcie albuminy od białka całkowitego, więc wynik łączy różne grupy o odmiennych zadaniach.||Wzrost może wynikać z szerokiej odpowiedzi immunologicznej lub przewagi ograniczonej populacji białek. Dopiero elektroforeza pomaga ocenić wzorzec; sama suma nie pozwala odróżnić odpowiedzi poliklonalnej od monoklonalnej.','Globuliny w zakresie nie wykluczają niedoboru określonej frakcji ani niewielkiego białka monoklonalnego. Przy podejrzeniu potrzebna jest ocena poszczególnych frakcji.','Stosunek A/G pokazuje relację, ale nie rozpoznaje sam konkretnej infekcji ani nowotworu. Uwzględnij także wiarygodność oznaczenia albuminy.');
add('glucose','Glukoza jest podstawowym paliwem wielu komórek. Jej stężenie wynika z równowagi między wchłanianiem, produkcją wątrobową i wykorzystaniem tkankowym. Insulina sprzyja wykorzystaniu i magazynowaniu, a hormony przeciwregulacyjne zwiększają dostępność w stresie lub głodzeniu.||Pojedynczy pomiar jest obrazem chwili. U kota stres może powodować znaczny przejściowy wzrost; utrzymującą się hiperglikemię ocenia się z objawami, glukozurią i markerami dłuższego okresu. Po pobraniu krwinki nadal zużywają glukozę, co może pozornie obniżyć wynik.','Glukoza w zakresie nie wyklucza epizodów hipo- lub hiperglikemii poza pobraniem. W monitorowaniu cukrzycy znaczenie ma przebieg i ryzyko hipoglikemii, nie pojedyncza poprawna liczba.','Przy niskim wyniku wyklucz opóźnione oddzielenie surowicy. Hipoglikemia z objawami neurologicznymi wymaga pilnej oceny, niezależnie od późniejszego wyniku.');
add('sodium','Sód jest głównym kationem płynu pozakomórkowego i istotnym wyznacznikiem toniczności. Jego stężenie opisuje przede wszystkim relację ilości sodu do wody, a nie bezpośrednio zapas sodu w całym organizmie.||Gospodarkę regulują pragnienie, ADH i mechanizmy nerkowe odpowiedzialne za zatrzymywanie wody oraz elektrolitów. Dlatego pacjent z niedoborem objętości może mieć mały, duży lub mieszczący się w zakresie sód, zależnie od składu utraconych płynów i uzupełniania wody.','Sód w zakresie nie wyklucza odwodnienia ani hipowolemii. Do oceny objętości potrzebne są badanie kliniczne, wywiad o stratach i pozostałe parametry.','Istotne są tempo narastania i objawy neurologiczne. Nie dobieraj sposobu korekcji wyłącznie z wielkości odchylenia; uwzględnij czas trwania zaburzenia.');
add('potassium','Potas jest głównym kationem wewnątrzkomórkowym i współtworzy potencjał błonowy mięśni oraz nerwów. Tylko niewielka część zasobów znajduje się we krwi, więc stężenie nie zawsze odpowiada całkowitemu zapasowi ustrojowemu.||Wynik zależy od wydalania przez nerki, strat pokarmowych i przesunięć między komórkami a osoczem. Insulina, równowaga kwasowo-zasadowa i uszkodzenie komórek mogą zmieniać tę dystrybucję. Duże odchylenia wpływają na siłę mięśni i przewodzenie w sercu.','Potas w zakresie nie wyklucza niedoboru całkowitych zasobów, jeżeli przesunięcia z komórek maskują straty. Oceniaj przebieg choroby i zmiany po rozpoczęciu leczenia.','Przy wyniku niepasującym do obrazu sprawdź hemolizę i zanieczyszczenie EDTA. Objawy i EKG są ważne, ale brak typowych zmian EKG nie wyklucza zagrożenia.');
add('chloride','Chlorki są głównym anionem pozakomórkowym. Wspólnie z sodem uczestniczą w bilansie wody, ale mają również istotny związek z równowagą kwasowo-zasadową i zawartością kwasu solnego w wydzielinie żołądkowej.||Wzrost lub spadek może wynikać z samej zmiany ilości wody albo z nieproporcjonalnej utraty lub podaży chlorków. Dlatego wynik należy zestawiać z sodem, a przy podejrzeniu zaburzeń kwasowo-zasadowych również z gazometrią lub wodorowęglanami.','Chlorki w zakresie nie wykluczają zaburzeń kwasowo-zasadowych ani mieszanych zmian. Ważna jest ich relacja do sodu i pozostałych jonów, nie wyłącznie położenie w przedziale.','Oceń rodzaj podawanych płynów i straty pokarmowe. Sam chlorek nie wystarcza do rozpoznania kwasicy lub zasadowicy.');
add('calcium','Wapń uczestniczy w przewodzeniu nerwowo-mięśniowym, skurczu mięśni i wielu reakcjach komórkowych. We krwi występuje jako frakcja zjonizowana, związana z białkami i w kompleksach. Aktywna biologicznie jest przede wszystkim frakcja zjonizowana.||Wapń całkowity zależy m.in. od albuminy, podczas gdy regulacja hormonalna reaguje na wapń zjonizowany. PTH, witamina D i nerki współtworzą homeostazę. Zmiana wapnia całkowitego nie zawsze oznacza podobną zmianę frakcji czynnej.','Wapń całkowity w zakresie nie wyklucza nieprawidłowego iCa. Gdy objawy lub choroba wskazują na zaburzenia wapniowe, rozważ bezpośrednie oznaczenie frakcji zjonizowanej.','Nie zastępuj iCa wzorem korekcyjnym z albuminy. Przy pomiarze iCa znaczenie mają pH, rodzaj próbki i kontakt z powietrzem.');
add('phosphorus','Fosforany uczestniczą w budowie kości, przemianach ATP, błon komórkowych i regulacji równowagi kwasowo-zasadowej. Większość zasobów znajduje się poza krwią; oznaczenie dotyczy krążących fosforanów nieorganicznych.||Stężenie zależy od wchłaniania jelitowego, wydalania nerkowego, wymiany z kością i przesunięć komórkowych. Wiek i wzrost wpływają na wynik. W chorobie nerek retencja fosforanów wiąże się ze zmianami regulacji mineralnej, ale wzrost może mieć także inne przyczyny.','Fosfor w zakresie nie wyklucza zaburzeń zasobów ani wczesnych zmian gospodarki mineralnej w PChN. Zestaw wynik z wiekiem, nerkami i wapniem.','Przy niskim stężeniu rozważ przesunięcia do komórek, m.in. po rozpoczęciu żywienia lub insulinoterapii. Znaczny spadek może wpływać na mięśnie i erytrocyty.');
add('magnesium','Magnez jest kofaktorem wielu reakcji enzymatycznych, zwłaszcza wykorzystujących ATP, i wpływa na pobudliwość nerwowo-mięśniową. Większość zasobów znajduje się w kości i komórkach, a tylko niewielka część w osoczu.||Na stężenie wpływa podaż, wchłanianie, straty pokarmowe i wydalanie nerkowe. Wynik całkowity nie jest tożsamy z frakcją zjonizowaną ani pełnym zapasem tkankowym. Zaburzenia magnezu mogą współistnieć z nieprawidłowym potasem i wapniem.','Magnez całkowity w zakresie nie wyklucza zubożenia zasobów. Przy utrzymujących się zaburzeniach potasu lub wapnia oceń także magnez i możliwe straty.','Pamiętaj o wydolności nerek oraz podawanych preparatach. Izolowany wynik bez oceny pozostałych elektrolitów może być niepełny.');
add('cholesterol','Cholesterol jest składnikiem błon i prekursorem kwasów żółciowych oraz hormonów steroidowych. Pochodzi z diety i syntezy ustrojowej, a we krwi jest transportowany w lipoproteinach.||Stężenie odzwierciedla metabolizm i transport lipidów, czynność wątroby, odpływ żółci oraz wpływ hormonów. Znaczenie u psa lub kota nie jest prostym odpowiednikiem oceny ryzyka sercowo-naczyniowego u człowieka.','Cholesterol w zakresie nie wyklucza choroby wątroby, jelit ani endokrynopatii. Jest elementem wzorca biochemicznego, a nie samodzielnym badaniem przesiewowym wszystkich tych chorób.','Przy wzroście oceń triglicerydy, białkomocz i kontekst hormonalny. Przy spadku uwzględnij wchłanianie, utratę jelitową i zdolność syntezy.');
add('triglycerides','Triglicerydy są transportowaną i magazynowaną postacią energii. Chylomikrony przenoszą tłuszcz pochodzący z jelit, a VLDL z wątroby. Wynik zależy od dopływu lipidów, ich wytwarzania i tempa usuwania z krążenia.||Po posiłku stężenie może przejściowo wzrosnąć. Utrwalona hipertriglicerydemia na czczo wymaga odróżnienia zaburzenia pierwotnego od wtórnego do chorób metabolicznych lub hormonalnych. Widoczna lipemia może też zakłócać inne oznaczenia.','Triglicerydy w zakresie nie wykluczają okresowych zaburzeń lipidowych ani choroby trzustki. Porównuj pomiary wykonane w podobnych warunkach żywienia.','Sprawdź, czy próbkę pobrano na czczo, jeśli stan pacjenta na to pozwalał. Samej mętności surowicy nie traktuj jako ilościowego wyniku.');
add('ldh','LDH katalizuje przemianę mleczanu i pirogronianu. Występuje w wielu tkankach, m.in. mięśniach, wątrobie i erytrocytach, dlatego całkowita aktywność we krwi jest mało swoista narządowo.||Uwalnianie z komórek może zwiększać wynik przy różnych uszkodzeniach, a hemoliza w próbce dodatkowo utrudnia ocenę. Rutynowy pomiar sumuje aktywność izoenzymów i nie określa, z którego narządu pochodzą.','LDH w zakresie nie wyklucza uszkodzenia konkretnej tkanki. Przy podejrzeniu choroby zwykle większą wartość mają bardziej swoiste markery i obraz kliniczny.','Nie utożsamiaj LDH ze stężeniem mleczanu ani nie lokalizuj uszkodzenia wyłącznie na podstawie LDH. Sprawdź hemolizę oraz CK, AST i inne dane.');
add('ck','CK umożliwia szybkie odtwarzanie ATP z wykorzystaniem fosfokreatyny w komórkach mięśniowych. Przy uszkodzeniu błon miocytów enzym przechodzi do krwi. Rutynowy pomiar dotyczy całkowitej aktywności, głównie związanej z mięśniami szkieletowymi.||Wynik może wzrosnąć po urazie, intensywnej pracy mięśni, drgawkach lub iniekcji domięśniowej, nie tylko w pierwotnej miopatii. Dynamika CK pomaga odróżniać utrzymujące się uszkodzenie od przemijającego epizodu.','CK w zakresie nie wyklucza każdej miopatii ani wcześniejszego epizodu uszkodzenia. Znaczenie ma moment pobrania i to, czy proces nadal trwa.','Porównaj z AST i wywiadem o wysiłku, drgawkach oraz zastrzykach. Całkowita CK nie jest swoistym testem uszkodzenia serca.');
add('amylase','Amylaza rozkłada wielocukry. Aktywność oznaczana w surowicy nie jest jednak swoistym pomiarem uwalniania wyłącznie z trzustki, a na wynik wpływają także procesy usuwania enzymu i choroby pozatrzustkowe.||Zwiększona aktywność może towarzyszyć zapaleniu trzustki, ale czułość i swoistość klasycznego oznaczenia są ograniczone. Mały wynik nie stanowi wiarygodnego testu niedoboru enzymów trawiennych; do oceny zewnątrzwydzielniczej funkcji trzustki służy TLI.','Amylaza w zakresie nie wyklucza zapalenia trzustki. W zależności od podejrzenia zestaw objawy z PLI i obrazowaniem.','Nie rozpoznawaj zapalenia trzustki z samej amylazy ani niewydolności zewnątrzwydzielniczej z jej niskiej aktywności. Oceń także nerki.');
add('lipase','Lipazy katalizują rozkład tłuszczów. Rutynowe testy aktywności mogą oznaczać działanie enzymów różnego pochodzenia; ich znaczenie zależy od substratu i metody, a nie tylko nazwy „lipaza” w raporcie.||Test immunoreaktywności lipazy trzustkowej cPL/fPL ocenia inny analit niż ogólna aktywność lipazy. Nie należy stosować tych samych progów ani traktować metod zamiennie. Rozpoznanie choroby trzustki opiera się na połączeniu danych klinicznych, laboratoryjnych i obrazowych.','Lipaza w zakresie, zwłaszcza w teście aktywności, nie wyklucza zapalenia trzustki. Nasilenie i czas procesu oraz użyta metoda wpływają na wykrywalność.','Najpierw ustal, jaki test wykonano. Niska aktywność nie rozpoznaje EPI, a wysoka bez kontekstu nie potwierdza zapalenia trzustki.');
add('fructosamine','Fruktozamina powstaje przez nieenzymatyczne wiązanie glukozy z białkami krwi, głównie albuminą. Odzwierciedla ekspozycję tych białek na glukozę w dłuższym okresie niż pojedynczy pomiar glikemii.||Na wynik wpływa nie tylko średnia glukoza, lecz także stężenie i tempo wymiany białek. Przy małej albuminie lub zwiększonym obrocie białkowym stężenie może być niższe mimo zaburzeń glikemii. Średnia nie pokazuje krótkich epizodów hipoglikemii i wahań w ciągu doby.','Fruktozamina w zakresie nie wyklucza świeżej cukrzycy ani naprzemiennych wysokich i niskich glikemii. W kontroli leczenia oceń przebieg glukozy oraz objawy.','U kota zestaw wynik z wpływem stresu na glikemię i chorobami zmieniającymi obrót białek. Nie koryguj terapii tylko na podstawie tej średniej.');
add('iron','Żelazo jest niezbędne do syntezy hemu i działania wielu enzymów. W osoczu jest transportowane przez transferynę, ale oznaczenie krążącego żelaza nie mierzy bezpośrednio całych magazynów tkankowych.||Podczas zapalenia zmienia się dostępność żelaza dla erytropoezy; małe stężenie może wynikać z jego zatrzymywania w magazynach, bez rzeczywistego wyczerpania zapasów. Przewlekła utrata krwi może natomiast prowadzić do niedoboru. Odróżnienie tych mechanizmów wymaga oceny morfologii i szerszej gospodarki żelazowej.','Żelazo w zakresie nie wyklucza wczesnego niedoboru ani zaburzonej dostępności dla szpiku. Oceń trend, MCV, MCHC i kontekst krwawienia lub zapalenia.','Nie rozpoznawaj niedoboru żelaza z pojedynczego niskiego wyniku. Posiłek, suplementacja, hemoliza i pora pobrania mogą zmienić ocenę.');
add('copper','Miedź jest mikroelementem uczestniczącym w reakcjach enzymatycznych i przemianach żelaza. Jej metabolizm obejmuje wchłanianie, transport i magazynowanie w wątrobie oraz wydalanie z żółcią.||Stężenie we krwi nie jest prostą miarą ilości zgromadzonej w hepatocytach. W ocenie hepatopatii związanej z miedzią znaczenie mają obraz kliniczny, histopatologia i ilościowe oznaczenie w tkance; sama próbka krwi nie odtwarza rozmieszczenia w narządzie.','Miedź we krwi w zakresie nie wyklucza nadmiernego gromadzenia w wątrobie. Nie używaj tego wyniku do samodzielnego wykluczenia hepatopatii miedziowej.','Rozróżniaj badanie krwi od ilościowej oceny tkanki. Suplementacja lub leczenie chelatujące nie powinny wynikać wyłącznie z pojedynczego stężenia.');
add('zinc','Cynk jest składnikiem wielu enzymów i białek regulacyjnych, istotnym m.in. dla nabłonków i metabolizmu. Jego dostępność zależy od podaży oraz wchłaniania, a stężenie krążące nie opisuje wprost zaopatrzenia każdej tkanki.||Duża ekspozycja może wywoływać zatrucie z objawami pokarmowymi i uszkodzeniem erytrocytów. Ocena toksykologiczna jest innym problemem niż poszukiwanie niedoboru żywieniowego. Rodzaj ekspozycji i jakość próbki mają duże znaczenie.','Cynk w zakresie nie wyklucza wszystkich zaburzeń skórnych związanych z jego metabolizmem. Rozpoznanie wymaga uwzględnienia diety, rasy, obrazu zmian i innych przyczyn.','Sprawdź ryzyko zanieczyszczenia próbki oraz kontaktu z metalowymi przedmiotami lub preparatami. Nadmiar i niedobór wymagają odmiennej interpretacji.');
add('uric-acid','Kwas moczowy jest produktem przemian puryn. U większości psów i kotów podlega dalszym przemianom, dlatego jego znaczenie różni się od rutynowej interpretacji u człowieka. Wynik zależy od metabolizmu, transportu i wydalania.||Nieprawidłowości związane z wydalaniem moczanów wymagają oceny gatunku, rasy i chorób wpływających na metabolizm. Stężenie we krwi nie jest równoważne ilości wydalanej z moczem ani analizie składu kamienia.','Wartość w zakresie nie wyklucza moczanowej kamicy ani zaburzeń metabolizmu puryn. Oceniaj mocz, obrazowanie i analizę materiału, jeżeli występują kamienie.','Nie przenoś schematu rozpoznawania dny moczanowej z medycyny człowieka. Potwierdź, czy wynik ma znaczenie w konkretnym problemie pacjenta.');
add('t3','T3 jest aktywnym hormonem tarczycowym powstającym także z obwodowej przemiany T4. Jego dostępność zależy od wydzielania tarczycy, konwersji tkankowej, wiązania z białkami i eliminacji.||Rutynowe T3 całkowite nie jest prostą miarą działania hormonu w każdej tkance. Choroby pozatarczycowe i leki mogą zmieniać metabolizm hormonów bez pierwotnej choroby tarczycy. W diagnostyce psa i kota test ma inne ograniczenia niż samo oznaczenie T4.','T3 w zakresie nie wyklucza niedoczynności tarczycy u psa ani nadczynności u kota. Wynik trzeba zestawić z lepiej dostosowanymi do podejrzenia badaniami i objawami.','Nie rozpoznawaj ani nie wykluczaj choroby wyłącznie z T3. Zwróć uwagę na leczenie, choroby współistniejące i możliwość interferencji immunologicznej.');
add('t4','T4 jest głównym hormonem wydzielanym przez tarczycę i źródłem T3 dla tkanek. Większość krąży związana z białkami, dlatego T4 całkowite obejmuje zarówno frakcję związaną, jak i wolną.||Układ podwzgórze–przysadka–tarczyca reguluje wydzielanie przez sprzężenie zwrotne. Stężenie zależy też od chorób pozatarczycowych, leków i podaży lewotyroksyny. Niskie T4 nie oznacza automatycznie niedoboru produkcji tarczycowej, a interpretacja u kota z podejrzeniem nadczynności różni się od oceny psa.','Wynik w zakresie nie wyklucza wszystkich zaburzeń, zwłaszcza przy silnym podejrzeniu klinicznym. W monitorowaniu leczenia konieczny jest czas pobrania względem dawki i cel terapii.','Niskie T4 w chorobie ogólnej może być adaptacyjną zmianą. Sprawdź fT4, TSH i kontekst, zamiast utożsamiać jedną liczbę z niedoczynnością.');
add('ft3','fT3 oznacza wolną, niezwiązaną z białkami część T3. Frakcja ta jest związana z dostępnością hormonu dla tkanek, ale oznaczenie jej bardzo małego stężenia wymaga właściwie zwalidowanej metody.||Wynik zależy od wydzielania i konwersji hormonów oraz stanu chorobowego. U psów i kotów fT3 nie zastępuje standardowej oceny T4, fT4 i TSH w odpowiednim wskazaniu. Przydatność testu musi być rozpatrywana dla danego gatunku i metody.','fT3 w zakresie nie jest samodzielnym potwierdzeniem prawidłowej czynności tarczycy. Nie wyklucza choroby, jeżeli inne dane wskazują na zaburzenie osi.','Nie nadawaj fT3 większej swoistości tylko dlatego, że jest frakcją wolną. Sprawdź walidację oznaczenia i jego rzeczywistą rolę w danym problemie.');
add('ft4','fT4 jest wolną frakcją tyroksyny, pozostającą w równowadze z hormonem związanym z białkami. Jego oznaczenie może uzupełniać T4 całkowite, ale wynik zależy od sposobu oddzielania i pomiaru wolnego hormonu.||Metoda dializy równowagowej i inne testy nie są automatycznie wymienne. Choroby pozatarczycowe nadal mogą wpływać na ocenę. U kota wysokie fT4 wymaga zestawienia z T4 i objawami, a u psa niskie fT4 z TSH i prawdopodobieństwem choroby.','fT4 w zakresie nie zamyka oceny, jeśli wynik nie pasuje do T4, TSH lub objawów. Uwzględnij metodę, leki i etap leczenia.','Nie traktuj pojedynczego podwyższenia fT4 u kota jako wystarczającego rozpoznania nadczynności. Interpretuj cały profil i choroby współistniejące.');
add('tsh','TSH jest hormonem przysadki pobudzającym tarczycę. Jego wydzielanie reaguje na sygnały osi hormonalnej, zwłaszcza sprzężenie zwrotne przez hormony tarczycy. Dlatego wynik opisuje reakcję układu, a nie samo stężenie hormonu docelowego.||Przy pierwotnej niedoczynności TSH może rosnąć, lecz nie u każdego chorego psa. Wartość testu zależy od gatunku, czułości oznaczenia i równoczesnego T4 lub fT4. Szczególnej ostrożności wymaga przenoszenie interpretacji testów między psami i kotami.','TSH w zakresie nie wyklucza niedoczynności u psa. Wynik może być nieadekwatny do niskiego T4, dlatego liczy się wspólna ocena hormonów i objawów.','W trakcie leczenia lub po terapii nadczynności interpretacja różni się od badania przesiewowego. Zwróć uwagę na gatunek i metodę oznaczenia.');
add('cortisol','Kortyzol jest hormonem kory nadnerczy regulowanym przez ACTH i sprzężenie zwrotne osi podwzgórze–przysadka–nadnercza. Wpływa na metabolizm i odpowiedź na stres, a jego wydzielanie jest zmienne w czasie.||Pojedyncze stężenie podstawowe nie opisuje pełnej rezerwy wydzielniczej ani zdolności hamowania osi. Stres i choroby ogólne mogą zwiększać wynik, a glikokortykosteroidy wpływać biologicznie lub zakłócać oznaczenie. Testy dynamiczne odpowiadają na inne pytania niż pomiar podstawowy.','Kortyzol w zakresie nie potwierdza prawidłowego działania całej osi. Interpretacja zależy od tego, czy badano próbkę podstawową, po stymulacji czy po hamowaniu.','Nie rozpoznawaj Cushinga z wysokiego kortyzolu podstawowego ani Addisona wyłącznie z małego. Stosuj właściwy dla podejrzenia protokół i oceniaj leki.');
add('phenobarbital','Fenobarbital jest lekiem, a nie naturalnym parametrem fizjologicznym. Oznaczenie stężenia służy ocenie ekspozycji organizmu podczas leczenia. Wynik zależy od dawki, wchłaniania, metabolizmu, interakcji i regularności podawania.||Zmiana dawkowania nie musi od razu dawać stężenia stacjonarnego. Porównywanie oznaczeń wymaga znajomości czasu od rozpoczęcia lub modyfikacji terapii oraz pory pobrania względem podania. Skuteczność kliniczna i działania niepożądane są równie ważne jak liczba.','Stężenie w zakresie terapeutycznym nie gwarantuje kontroli napadów ani braku toksyczności. Oceń częstość napadów, samopoczucie, biochemię i indywidualną odpowiedź pacjenta.','Nie zmieniaj dawki automatycznie po jednym oznaczeniu. Ustal czas pobrania, regularność podawania i czy osiągnięto stan stacjonarny.');
add('insulin','Insulina jest wydzielana przez komórki beta trzustki w odpowiedzi na bodźce metaboliczne, przede wszystkim glukozę. Sprzyja wykorzystaniu i magazynowaniu substratów oraz ogranicza produkcję glukozy. Jej stężenie powinno być oceniane w relacji do równoczesnej glikemii.||Przy hipoglikemii fizjologicznie oczekuje się zahamowania wydzielania. Wynik mieszczący się w populacyjnym zakresie może być zatem nieadekwatnie wysoki dla tej sytuacji. Z kolei wysokie stężenie przy hiperglikemii może oznaczać odpowiedź na insulinooporność, nie samodzielnie guz.','Insulina w zakresie nie oznacza prawidłowej regulacji, jeżeli glukoza jest niska. Zawsze interpretuj parę wyników z tej samej sytuacji klinicznej.','Uwzględnij podawanie insuliny i reakcję krzyżową testu. Nie prowokuj hipoglikemii ani nie rozpoznawaj insulinoma z samego stężenia bez udokumentowanej glikemii.');
for(const sex of ['male','female'])add('estradiol-'+sex,'Estradiol jest estrogenem wpływającym na tkanki rozrodcze i liczne procesy ogólnoustrojowe. Jego stężenie zależy od czynności gonad, etapu cyklu, kastracji i ewentualnej ekspozycji na hormony.||Pojedynczy pomiar jest fragmentem zmiennego profilu. Interpretacja wymaga znajomości płci, stanu rozrodczego i objawów. Nie każde odchylenie potwierdza obecność czynnej tkanki gonadalnej lub nowotworu, a wybór testu zależy od pytania klinicznego.',sex==='female'?'Wynik w zakresie nie wyklucza zmian zależnych od fazy cyklu ani pozostałości jajnika. Potrzebne są wywiad, objawy i ewentualne badania lepiej odpowiadające podejrzeniu.':'Wynik w zakresie nie wyklucza choroby gonad. Przy feminizacji lub podejrzeniu ekspozycji na estrogeny oceń obraz kliniczny, gonady i pozostałe wyniki.','Sprawdź zakres właściwy dla płci i metody. Duże znaczenie ma kastracja oraz możliwy kontakt z preparatami hormonalnymi stosowanymi u opiekuna.');
for(const sex of ['male','female'])add('testosterone-'+sex,'Testosteron jest androgenem, którego stężenie zależy od czynności tkanek steroidogennych i regulacji hormonalnej. Ocenę należy powiązać z płcią, wiekiem i obecnością gonad. Wydzielanie może być zmienne, dlatego pojedyncza mała wartość nie zawsze oznacza brak czynnej tkanki.||Test podstawowy i test po stymulacji odpowiadają na różne pytania. Przy podejrzeniu wnętrostwa lub pozostałości tkanki gonadalnej dobór badania powinien uwzględniać czułość testu i możliwość wykorzystania innych markerów.',sex==='male'?'Testosteron w zakresie nie potwierdza płodności ani prawidłowej budowy jąder. Pojedynczy niski wynik nie wyklucza obecności tkanki jądrowej.':'Wynik w zakresie nie wyklucza wszystkich przyczyn objawów androgenizacji. Rozważ źródła gonadalne, nadnerczowe i egzogenną ekspozycję zależnie od obrazu.','Nie interpretuj wyniku bez informacji o kastracji i wskazaniu do testu. Nie stosuj zakresu samca do samicy ani zakresu podstawowego do próbki po stymulacji.');
add('pth','PTH jest wydzielany przez przytarczyce przede wszystkim w odpowiedzi na stężenie wapnia zjonizowanego. Współreguluje gospodarkę wapniowo-fosforanową przez wpływ na kość, nerki i metabolizm witaminy D.||Wynik jest odpowiedzią regulacyjną, więc należy oceniać jego adekwatność. Przy wysokim iCa oczekuje się zahamowania PTH; wartość „w zakresie” może wtedy oznaczać nieprawidłowy brak supresji. Przy małym iCa wzrost może być prawidłową odpowiedzią wtórną.','PTH w zakresie może być nieadekwatne do równoczesnego iCa. Populacyjny przedział nie zastępuje oceny sprzężenia zwrotnego. Uwzględnij fosfor i nerki.','PTH i wapń zjonizowany oceniaj łącznie, najlepiej w powiązanym pobraniu. Sprawdź wymagania laboratorium dotyczące stabilności, przechowywania i transportu próbki.');
add('b12','Kobalamina jest kofaktorem reakcji metabolicznych wewnątrz komórek. Jej prawidłowe wykorzystanie wymaga odpowiedniej podaży, procesu wiązania i wchłaniania w jelicie krętym oraz współpracy z wydzielaniem trzustki.||Małe stężenie może towarzyszyć przewlekłej enteropatii lub niewydolności zewnątrzwydzielniczej trzustki. Oznaczenie we krwi nie jest bezpośrednim pomiarem każdej puli tkankowej; kwas metylomalonowy może w określonych sytuacjach uzupełniać ocenę funkcjonalnego niedoboru.','B12 w zakresie nie wyklucza choroby jelita ani trzustki. Niedawna suplementacja zmienia znaczenie pomiaru; oceniaj go z objawami i terminem podania preparatu.','Niedobór może pogarszać odpowiedź na leczenie choroby przewodu pokarmowego. Nie pomijaj przyczyny zaburzonego wchłaniania, nawet gdy uzupełniasz witaminę.');
add('tli','TLI mierzy immunoreaktywność związaną głównie z trypsynogenem pochodzącym z komórek pęcherzykowych trzustki. Mała ilość trafia do krwi w prawidłowych warunkach, a znaczny ubytek czynnej tkanki zewnątrzwydzielniczej może zmniejszyć stężenie.||Test jest gatunkowo swoisty i służy przede wszystkim ocenie niewydolności zewnątrzwydzielniczej. Wysokie TLI nie jest swoistym dowodem zapalenia trzustki. Progi decyzyjne zależą od testu i jego aktualnej walidacji; nie należy przenosić ich bezpośrednio między laboratoriami.','TLI w zakresie nie wyklucza zapalenia trzustki ani innej przyczyny zaburzeń trawienia. PLI i TLI oceniają różne aspekty trzustki.','Przy granicznym obniżeniu sprawdź warunki pobrania i aktualne progi testu. Oceniaj także B12; wynik nie zastępuje całości obrazu klinicznego.');
add('usg','Ciężar właściwy opisuje gęstość moczu względem wody i zależy od ilości oraz rodzaju rozpuszczonych substancji. Zdolność do zagęszczania wymaga sprawnych kanalików, odpowiedzi na ADH i utrzymania gradientu osmotycznego w rdzeniu nerki.||Niski wynik może być właściwą odpowiedzią na nadmiar wody albo skutkiem zaburzonego zagęszczania. Ta sama wartość ma inne znaczenie u nawodnionego pacjenta po płynach i u odwodnionego z azotemią. Glukoza i duże ilości białka mogą zwiększać gęstość bez odpowiedniej oszczędności wody.','Nie istnieje jedna wartość właściwa dla każdej sytuacji. Oczekiwana koncentracja zależy od nawodnienia, gatunku, diety i leczenia; „w zakresie” nie oznacza automatycznie odpowiedniego zagęszczania.','Oceniaj refraktometrem odpowiednim do badania moczu. Pojedynczy rozcieńczony mocz nie rozpoznaje PChN, a koncentracja nie zastępuje oceny filtracji.');
add('upc','UPC odnosi stężenie białka w moczu do stężenia kreatyniny, ograniczając wpływ rozcieńczenia pojedynczej próbki. Pomaga oceniać nasilenie białkomoczu, ale nie rozpoznaje automatycznie źródła białka.||Białko może trafiać do moczu przednerkowo, wskutek zaburzeń kłębuszków lub kanalików, albo z krwi i zapalenia dróg moczowych. Utrwalony białkomocz nerkowy ma inne znaczenie niż przejściowa zmiana lub wynik przy aktywnym osadzie.','Małe UPC nie wyklucza choroby nerek bez białkomoczu ani zmian okresowych. Wartość graniczna wymaga oceny utrzymywania się i warunków pobrania.','Przed przypisaniem wzrostu nerkom oceń osad i krwawienie. Do interpretacji wykorzystuj kryteria właściwe dla gatunku i nie utożsamiaj UPC z pomiarem GFR.');
add('ph','pH określa odczyn moczu, wynikający z wydalania kwasów i zasad oraz działania buforów. Wpływają na nie dieta, stan metaboliczny, pory karmienia, czynność kanalików i niektóre drobnoustroje.||Odczyn ma znaczenie dla rozpuszczalności składników moczu i powstawania części kryształów. Nie odtwarza jednak bezpośrednio pH krwi. Próbka zmienia się podczas przechowywania, więc wynik ze starego moczu może nie opisywać stanu w pęcherzu.','Odczyn oczekiwany w danym kontekście nie wyklucza zakażenia ani kamicy. Nie ma jednej idealnej wartości pH dla każdego pacjenta i każdego typu kryształu.','Nie rozpoznawaj zakażenia z samego zasadowego pH ani kwasicy ustrojowej z kwaśnego moczu. Uwzględnij świeżość, dietę i metodę pomiaru.');
add('ur-rbc','Erytrocyty w osadzie wskazują na obecność krwi w próbce, ale źródło może obejmować nerki, drogi moczowe, narządy płciowe lub uraz podczas pobrania. Liczba zależy także od zagęszczenia moczu i sposobu przygotowania osadu.||Reakcja paska na hem wykrywa nie tylko zachowane krwinki, ale również hemoglobinę i mioglobinę. Przy lizie erytrocytów można więc uzyskać dodatnią reakcję przy małej liczbie widocznych komórek.','Brak istotnej liczby RBC nie wyklucza okresowego krwawienia ani rozpadu krwinek w rozcieńczonej lub starej próbce. Zestaw osad z reakcją na hem.','Rozróżniaj rzeczywisty krwiomocz od zanieczyszczenia podczas pobrania. Sama liczba RBC nie lokalizuje miejsca krwawienia.');
add('ur-protein','Pole białkowe paska reaguje głównie na albuminę i daje wynik półilościowy. Ten sam stopień dodatniości ma inne znaczenie w moczu bardzo rozcieńczonym i silnie zagęszczonym. Nie jest to bezpośrednia dobowa utrata białka.||Białkomocz może wynikać z przepuszczalności bariery kłębuszkowej, zaburzeń kanalikowych lub dodania białka przez krwawienie i zapalenie. Do ilościowego uzupełnienia służy UPC, po ocenie osadu i możliwego pochodzenia pozanerkowego.','Ujemny pasek nie wyklucza niewielkiej utraty białka ani białek słabo wykrywanych tą metodą. Przy podejrzeniu klinicznym dobierz badanie do pytania, zamiast kończyć ocenę na pasku.','Nie stopniuj choroby nerek według liczby plusów. Sprawdź ciężar właściwy, osad, warunki odczytu i ewentualną potrzebę oznaczenia UPC.');
add('ur-bacteria','Obecność bakterii w osadzie oznacza ich wykrycie w próbce. Może odzwierciedlać zakażenie, bakteriurię bez objawów lub zanieczyszczenie przy pobraniu. Mocz z mikcji i z cystocentezy wymaga innej oceny ryzyka kontaminacji.||Po pobraniu bakterie mogą namnażać się w nieprawidłowo przechowywanym materiale. Obserwacja w osadzie nie podaje gatunku ani lekowrażliwości; posiew odpowiada na inne pytania niż sama mikroskopia.','Brak widocznych bakterii nie wyklucza zakażenia, szczególnie przy małej liczbie, rozcieńczeniu lub wcześniejszym antybiotyku. O potrzebie posiewu decyduje cały obraz kliniczny.','Oceń objawy, leukocyty, sposób pobrania i świeżość. Sama bakteriuria nie stanowi automatycznego wskazania do antybiotykoterapii.');
add('ur-crystals','Krystaluria powstaje, gdy warunki sprzyjają wytrącaniu związków z moczu. Znaczenie mają stężenie substancji, pH, temperatura i inhibitory krystalizacji. Kryształy mogą tworzyć się w organizmie albo dopiero po pobraniu.||Ocena wymaga nazwania typu, a nie wyłącznie określenia liczby. Nieliczne kryształy spotykane u zdrowych zwierząt mają inne znaczenie niż kryształy sugerujące zaburzenia metabolizmu lub ekspozycję na określone substancje.','Brak kryształów nie wyklucza kamicy. Skład kamienia nie musi odpowiadać aktualnym kryształom w pojedynczej próbce; najpewniejsza jest analiza uzyskanego materiału.','Nie rozpoznawaj kamicy tylko z krystalurii. Zestaw świeży osad z objawami, odczynem moczu i obrazowaniem.');
add('ur-casts','Wałeczki powstają w świetle kanalików na białkowej matrycy i mogą zawierać komórki lub ich pozostałości. Ich kształt odzwierciedla miejsce powstawania, dlatego informują o procesach w nefronie, a nie tylko w dolnych drogach moczowych.||Wałeczki szkliste, ziarniste, komórkowe i inne mają różne znaczenie. Liczba zależy również od momentu pobrania i trwałości w próbce. Rozcieńczenie, zasadowy odczyn i zwłoka mogą prowadzić do rozpadu i zaniżenia obserwowanej liczby.','Brak wałeczków nie wyklucza choroby nerek ani uszkodzenia kanalikowego. Ich wydalanie może być nieregularne, a próbka nie zachowywać pierwotnego obrazu.','Zapisuj typ i ilość z jednostką raportu. Same wałeczki nie określają GFR ani rozległości trwałego uszkodzenia nerek.');
add('creat','Kreatynina powstaje podczas przemian kreatyny i fosfokreatyny w mięśniach. Jej produkcja zależy od masy mięśniowej, dlatego stężenie należy oceniać w kontekście budowy pacjenta.||Jest swobodnie filtrowana w kłębuszkach. Zmniejszenie filtracji zwiększa jej stężenie, ale zależność jest nieliniowa i wczesna choroba może nie powodować przekroczenia zakresu.','Wynik w zakresie nie wyklucza wczesnej choroby nerek. Ważny jest utrzymujący się trend, SDMA, badanie moczu i ocena umięśnienia pacjenta.','Rozróżniaj przyczyny przednerkowe, nerkowe i pozanerkowe. Oceniaj także masę mięśniową, nawodnienie i warunki wykonania pomiaru.');
const analysis={
hct:'Porównanie HCT z białkiem całkowitym pomaga rozważyć zmianę objętości osocza, ale nie stanowi samodzielnego rozróżnienia krwawienia i hemolizy. Przy spadku oceniaj retikulocyty, bilirubinę, wygląd osocza i ślady utraty krwi. Objawy ciężkiej niedokrwistości mogą wystąpić przy różnym HCT, zależnie od szybkości zmiany. Wynik po płynach interpretuj jako pomiar w nowych warunkach nawodnienia.',
rbc:'Małe RBC z małym HCT i HGB potwierdza spójność obrazu niedokrwistości. Przy niezgodności tych parametrów rozważ wielkość komórek i artefakty przed wnioskowaniem o chorobie szpiku. Retikulocytoza wspiera zwiększoną produkcję, lecz jej adekwatność zależy od nasilenia niedokrwistości. Zmiany jednej linii komórkowej różnią się od jednoczesnego spadku erytrocytów, leukocytów i płytek.',
hgb:'Jeżeli HGB jest nieproporcjonalnie wysokie do HCT, sprawdź MCHC oraz barwę i przejrzystość osocza. To może ujawnić problem pomiarowy zamiast rzeczywistej zmiany krwinek. Niskie HGB z małym MCV i MCHC wspiera ocenę mikrocytarnej, niedobarwliwej niedokrwistości, ale jej przyczynę trzeba ustalić z wywiadu, rozmazu i gospodarki żelazowej.',
mcv:'Makrocytozę z retikulocytozą oceniaj inaczej niż makrocytozę bez odpowiedzi regeneracyjnej. W drugim przypadku poza przechowywaniem próbki rozważ zaburzenia dojrzewania i cechy rasowe. Mikrocytoza wraz z niedobarwliwością zwiększa znaczenie poszukiwania przewlekłej utraty żelaza, ale może też występować w innych procesach. Sam kierunek MCV nie jest podstawą suplementacji.',
mch:'Wysokie MCH z wysokim MCV może wynikać z większych komórek, nawet gdy MCHC nie wzrosło. Wysokie MCH z nieproporcjonalnym HGB wymaga natomiast kontroli próbki. W praktyce traktuj je jako część układu wzajemnie zależnych wskaźników. Oddzielna interpretacja każdego przekroczenia jako osobnej choroby prowadzi do mnożenia pozornych problemów.',
mchc:'MCHC jest użytecznym sprawdzianem spójności erytrogramu. Przy wysokim wyniku porównaj pomiar HGB, liczbę krwinek, MCV i ewentualnie PCV. Przy obniżeniu oceń retikulocyty i cechy niedoboru żelaza. Niedobarwliwość widoczna w rozmazie oraz obniżony wskaźnik są danymi uzupełniającymi; żadnego z nich nie należy interpretować w oderwaniu od niedokrwistości.',
rdw:'Wysokie RDW przy MCV w zakresie sugeruje potrzebę obejrzenia rozkładu komórek zamiast uznania ich za jednorodne. Rozmaz pozwala rozróżnić przewagę małych krwinek, dużych młodych komórek lub mieszanego obrazu. W monitorowaniu leczenia przejściowe poszerzenie rozkładu może odzwierciedlać współistnienie starszej i nowej populacji, więc znaczenie zależy od trendu HCT i retikulocytów.',
plt:'Rozróżnij krwawienia typowe dla hemostazy pierwotnej, takie jak wybroczyny i krwawienie śluzówkowe, od innych obrazów. Potwierdzona małopłytkowość wymaga oceny niszczenia, zużycia, sekwestracji i produkcji. Towarzyszące niedokrwistość lub leukopenia mogą poszerzać podejrzenia, ale same nie rozstrzygają mechanizmu. Prawidłowy PT i APTT nie unieważniają znaczenia zaburzeń płytek.',
mpv:'Duże płytki przy małym PLT mogą towarzyszyć odnowie populacji, ale nie dowodzą automatycznie immunologicznego niszczenia. Duże płytki mogą też być słabo rozpoznawane przez analizator. Przy sprzeczności pomiarów większą wartość ma dobrze wykonany rozmaz i weryfikacja liczby niż interpretacja izolowanego MPV. Uwzględnij, czy laboratorium uznało wskaźnik za wiarygodny.',
esr:'Wzrost OB z innymi markerami zapalenia wspiera obecność odpowiedzi ustrojowej, ale nie wskazuje jej przyczyny. Przy wysokim OB i niedokrwistości część zmiany może wynikać z erytrogramu. Dane dotyczące metody i gatunku są istotne: nie zakładaj, że badanie zwalidowane u psa daje identyczną wartość kliniczną u kota. Do monitorowania zachowaj tę samą metodę.',
wbc:'Analizuj wzorzec, nie tylko sumę: dojrzała neutrofilia z limfopenią może pasować do wpływu glikokortykosteroidów, natomiast lewy zwrot i toksyczne zmiany neutrofili wspierają odpowiedź zapalną. Żaden wzorzec nie zastępuje wywiadu. Nietypowe komórki lub utrzymująca się niewyjaśniona leukocytoza mogą wymagać dokładniejszej identyfikacji, zamiast przypisywania wszystkiego stresowi.',
bands:'Porównanie liczby form niedojrzałych i dojrzałych pomaga ocenić adekwatność odpowiedzi szpiku do zapotrzebowania. Lewy zwrot nie jest samodzielnym dowodem infekcji bakteryjnej: silne jałowe zapalenie również może go wywoływać. Zmiany toksyczne opisują zaburzenia dojrzewania w przyspieszonej granulopoezie, a nie wyłącznie działanie toksyn krążących w próbce.',
neut:'Neutrofilia z wyraźnym lewym zwrotem ma inny ciężar interpretacyjny niż izolowany wzrost dojrzałych komórek u pobudzonego zwierzęcia. Przy neutropenii sprawdź inne linie, leki i ryzyko upośledzenia szpiku, ale także objawy ciężkiego zapalenia. Kolejne pomiary pozwalają ocenić, czy odpowiedź się rozwija, stabilizuje, czy rezerwa komórkowa maleje.',
eos:'Wzrost eozynofili zestaw z badaniem skóry, przewodu pokarmowego i układu oddechowego. Wykrycie pasożyta lub choroby eozynofilowej wymaga odpowiednich badań, a nie samego odsetka. Eozynopenia często ma mniejszą wartość niż eozynofilia i może być częścią odpowiedzi na stres. Liczby bezwzględne są ważniejsze niż zmiana procentu wynikająca z neutrofilii.',
baso:'Bazofilia z eozynofilią może kierować uwagę na wspólne bodźce zapalne, ale izolowany wynik wymaga potwierdzenia. Ponieważ komórki są rzadkie, mała liczba znalezionych bazofili może dawać duże względne różnice między rozmazami. Utrwalona, wyraźna zmiana z nieprawidłowościami innych komórek zasługuje na szerszą ocenę niż pojedyncze niewielkie przekroczenie.',
lymph:'Przy limfocytozie oceniaj jednorodność i dojrzałość komórek oraz utrzymywanie się zmiany. Duże reaktywne limfocyty nie są automatycznie komórkami nowotworowymi. Przy limfopenii porównaj obraz z wpływem glikokortykosteroidów, chorobą ogólną i możliwymi stratami. Sam odsetek może maleć tylko dlatego, że wzrosła inna populacja; sprawdź liczbę bezwzględną.',
mono:'Monocytoza z neutrofilią i limfopenią u psa może być elementem wpływu kortykosteroidów, ale także towarzyszyć zapaleniu. W rozmazie zwróć uwagę na aktywację i poprawność odróżnienia monocytów od innych dużych komórek. Rozpoznanie choroby rozrostowej wymaga szerszych danych niż sama liczba. Utrwalony trend ma większą wartość niż izolowane niewielkie odchylenie.',
anisocytosis:'Warto opisać, czy różnorodność wynika głównie z mikrocytów, makrocytów czy mieszanego obrazu. Anizocytoza z polichromazją i retikulocytozą wspiera odnowę krwinek; bez nich wymaga innego wyjaśnienia. Prawidłowa średnia MCV może ukrywać taki mieszany obraz. Skala plusowa jest półilościowa i nie zawsze identyczna między osobami oceniającymi preparat.',
polychromasia:'Nasilona polichromazja z retikulocytozą pozwala wiązać zmianę z produkcją młodych komórek. Brak odpowiedniej odpowiedzi przy dużej niedokrwistości wymaga uwzględnienia czasu i czynników ograniczających erytropoezę. U kota długo utrzymujące się retikulocyty punkcikowate mogą zmieniać MCV bez proporcjonalnej polichromazji, dlatego nie oceniaj bieżącej regeneracji z jednego wskaźnika.',
poikilocytosis:'Poproś o określenie dominujących postaci, np. fragmentów, komórek o zmienionej błonie lub obrazu sugerującego stres oksydacyjny. Te wzorce mogą kierować dalszą oceną, lecz nie są zawsze swoiste. Jakość obszaru rozmazu jest szczególnie ważna przy podejrzeniu sferocytów i innych zmian kształtu. Zbiorczy zapis „poikilocytoza” ma ograniczoną wartość bez doprecyzowania.',
nrbc:'Obecność nRBC z wyraźną retikulocytozą może być częścią odnowy, natomiast ich duża liczba bez odpowiedzi regeneracyjnej wymaga oceny innych mechanizmów. Zestaw wynik z rozmazem, objawami niedotlenienia i stanem szpiku. Laboratorium powinno rozróżniać liczbę na 100 leukocytów od stężenia bezwzględnego; te formy raportowania nie są zamienne.',
retic:'Przy ocenie odpowiedzi szpiku najpierw ustal, czy pacjent ma niedokrwistość i jak głęboką. Wysoka liczba retikulocytów może występować również bez aktualnie małego HCT, np. w fazie odnowy. Mały wynik przy anemii może wynikać z wczesnej fazy, zapalenia, choroby nerek lub zaburzeń szpiku. Różnicowanie wymaga pełnego erytrogramu.',
pt:'Izolowane wydłużenie PT i jednoczesne wydłużenie PT z APTT wskazują na różne zestawy możliwych zaburzeń. Przy podejrzeniu działania antagonistów witaminy K znaczenie ma czas od ekspozycji. Nieprawidłowa próbka może naśladować niedobór czynników. Oceniaj także PLT, fibrynogen, chorobę wątroby i objawy, zamiast przypisywać każdy długi czas jednej przyczynie.',
aptt:'Wydłużenie APTT przy prawidłowym PT może pasować do zaburzenia szlaku wewnątrzpochodnego lub inhibitora, ale nasilenie nie zawsze odpowiada ryzyku krwawienia. Wydłużenie obu czasów poszerza ocenę na szlak wspólny i zaburzenia wieloczynnikowe. Przed diagnostyką niedoborów sprawdź pobranie, cytrynian i możliwość obecności heparyny.',
fibrinogen:'Mały fibrynogen z wydłużonymi czasami i małopłytkowością wymaga oceny zużycia lub poważnego zaburzenia syntezy. Wysoki wynik może towarzyszyć zapaleniu, ale nie określa jego miejsca. Jednoczesne pobudzenie syntezy i zużycie mogą dać pozornie poprawne stężenie. Dlatego do oceny dynamicznego procesu większą wartość ma zestaw wyników i ich trend.',
ast:'AST z wyraźnym wzrostem CK przemawia za rozważeniem źródła mięśniowego. AST z ALT i innymi zmianami wątrobowymi wymaga oceny hepatocytów. Oba źródła mogą współistnieć, np. u ciężko chorego pacjenta. Zmiana po drgawkach lub urazie ma inne tło niż utrwalony wzrost bez objawów mięśniowych; czas pobrania pomaga wyjaśnić rozbieżności.',
alt:'Dominujący wzrost ALT tworzy wzorzec uszkodzenia hepatocytów, ale możliwe są przyczyny zapalne, toksyczne, niedotlenieniowe i wtórne do chorób pozawątrobowych. Równoczesna ALP, GGT i bilirubina pomagają ocenić udział cholestazy. Albumina, glukoza, mocznik i odpowiednio dobrane testy funkcjonalne odpowiadają na inne pytania. Prawidłowy wynik tych testów nie unieważnia aktywnego uszkodzenia.',
alp:'Wzrost ALP u rosnącego psa albo leczonego glikokortykosteroidami ma inny punkt wyjścia niż u dorosłego kota. Nie oznacza to automatycznie braku choroby wątroby: kilka mechanizmów może działać równocześnie. Oceń leki, ALT, GGT, bilirubinę i obrazowanie. Duże ALP nie wskazuje samo stopnia niewydolności ani konieczności konkretnego leczenia.',
ggt:'Proporcje ALP i GGT mogą pomagać w ocenie procesu, lecz nie są rozpoznaniem histopatologicznym. Przy wzroście obu enzymów i bilirubiny rozważ chorobę dróg żółciowych oraz cholestazę, ale odróżnienie procesu wewnątrz- i zewnątrzwątrobowego wymaga dalszych danych. U kota nieproporcjonalnie wysokie ALP przy małym GGT jest wzorcem wartym uwagi, nie samodzielnym dowodem jednej choroby.',
gldh:'Łączny wzrost GLDH i aminotransferaz wspiera ocenę uszkodzenia hepatocytów, ale mechanizm toksyczny, niedotlenieniowy czy zapalny wymaga wywiadu i dodatkowych badań. Wartość mitochondrialnego enzymu nie powinna być przeliczana na procent uszkodzonej wątroby. Równie ważne są objawy, zdolność syntezy i przebieg zmian w kolejnych próbkach.',
bilirubin:'Przy małym HCT, cechach regeneracji i zmianach sugerujących hemolizę rozważ zwiększoną produkcję bilirubiny. Przy dominujących markerach cholestazy większe znaczenie ma odpływ żółci, ale proces mieszany jest możliwy. Oceniaj także choroby ogólne i apetyt. Frakcjonowanie może pomóc, lecz nie wyznacza samo miejsca ani przyczyny zaburzenia.',
urea:'Mocznik znacznie wyższy w relacji do kreatyniny skłania do oceny perfuzji, katabolizmu i krwawienia do przewodu pokarmowego. Mały mocznik może wynikać z małej podaży białka, rozcieńczenia lub upośledzonej syntezy, a nie nadzwyczaj dobrej filtracji. Rozbieżności interpretuj razem z nawodnieniem, mięśniami, wątrobą i badaniem moczu, bez stosowania samego stosunku jako rozpoznania.',
sdma:'Rozbieżność między SDMA a kreatyniną jest sygnałem do oceny umięśnienia, zmienności wyniku i momentu choroby. Wzrost obu markerów zwiększa znaczenie spadku filtracji, lecz nadal nie określa przyczyny. Przy utrzymującej się zmianie ważne są ciężar właściwy, osad, UPC i obrazowanie. Kryteria klasyfikacji PChN stosuje się dopiero po jej rozpoznaniu i ocenie stabilności.',
"total-protein":'Odwodnienie może zwiększyć zarówno albuminę, jak i globuliny. Duże globuliny z małą albuminą kierują uwagę na inny mechanizm niż równoległy wzrost obu frakcji. Przy niskiej sumie oceń utratę, rozcieńczenie i syntezę. Suma nie pokaże, czy wzrost konkretnej frakcji jest poliklonalny lub monoklonalny; do tego służy odpowiednio dobrana elektroforeza.',
albumin:'Hipoalbuminemia z białkomoczem wymaga oceny nerkowej utraty, natomiast z objawami jelitowymi może kierować uwagę na enteropatię z utratą białka. Małe stężenie nie rozstrzyga między tymi procesami i zaburzeniem syntezy. Uwzględnij globuliny, cholesterol, mocz oraz markery wątrobowe. Wiązanie leków i części minerałów przez albuminę sprawia, że jej spadek wpływa również na interpretację innych wyników.',
globulin:'Duże globuliny nie dowodzą konkretnej infekcji. Wzorzec poliklonalny częściej wiąże się z szeroką odpowiedzią immunologiczną, a ograniczony pik wymaga innej oceny, lecz elektroforeza również musi być interpretowana klinicznie. Przy małym stężeniu rozważ utratę białka, stan immunologiczny i wiek. Nie używaj samego A/G do potwierdzania FIP ani nowotworu.',
glucose:'Hiperglikemię z glukozurią i objawami wzmożonego pragnienia interpretuj inaczej niż izolowany wzrost u zestresowanego kota. Fruktozamina może pomóc ocenić dłuższy okres, ale ma własne ograniczenia. Przy hipoglikemii zestaw pomiar z objawami, jakością próbki, leczeniem i ewentualną równoczesną insuliną. Prawidłowy pomiar między epizodami nie wyjaśnia nawracających zasłabnięć.',
sodium:'Oceń najpierw, czy problem dotyczy przewagi utraty lub zatrzymania wody, czy złożonej zmiany bilansu płynów. Pragnienie, dostęp do wody, straty i płynoterapia są podstawowymi danymi. Przy niezgodności z obrazem pacjenta sprawdź metodę pomiaru i ewentualny wpływ dużej lipemii lub białek na pomiar pośredni. Samo stężenie nie określa objętości krwi krążącej.',
potassium:'Hiperkaliemia przy zaburzeniu odpływu moczu lub małej diurezie ma inne tło niż pozorny wzrost w uszkodzonej próbce. Hipokaliemia może wynikać ze strat nerkowych, pokarmowych lub przesunięcia do komórek. Zmiana po insulinie nie musi oznaczać uzupełnienia zasobów. Oceń kreatyninę, diurezę, równowagę kwasowo-zasadową i leki, a także ryzyko zaburzeń rytmu.',
chloride:'Proporcjonalna zmiana sodu i chlorków może wskazywać na wpływ bilansu wody. Nieproporcjonalna zmiana chlorków skłania do dokładniejszej oceny kwasowo-zasadowej, strat żołądkowych i podaży płynów. Prawidłowe pH krwi może współistnieć z zaburzeniem mieszanym, więc nie kończ oceny na jednej liczbie. Interpretuj z gazometrią, a nie zamiast niej.',
calcium:'Przy wysokim iCa oceń, czy PTH jest odpowiednio zahamowane; stężenie PTH w populacyjnym zakresie może być nieadekwatne. Przy niskim wapniu całkowitym z małą albuminą bezpośredni iCa pomaga odróżnić problem frakcji związanej od rzeczywistej hipokalcemii. Fosfor, nerki, leki i wywiad o ekspozycji uzupełniają różnicowanie. Nie każda hiperkalcemia oznacza nowotwór.',
phosphorus:'Wysoki fosfor z azotemią wspiera ocenę retencji, ale uwzględnij wiek oraz inne przyczyny wzrostu. Mały fosfor podczas leczenia może odzwierciedlać przesunięcie do komórek, a nie tylko małą podaż. Zmiany fosforu należy zestawiać z wapniem, nerkami i planem żywienia. Długotrwałe zaburzenie mineralne wymaga oceny regulacji hormonalnej, nie pojedynczej korekty liczby.',
magnesium:'Hipomagnezemia może współuczestniczyć w utrzymujących się zaburzeniach potasu i wapnia, dlatego ich ocena łączna jest bardziej użyteczna. Duże stężenie przy upośledzeniu wydalania i podaży magnezu ma inne znaczenie niż odchylenie w próbce z interferencją. Nie utożsamiaj całkowitego magnezu z frakcją czynną; dostępność właściwego badania i jego wymagania należy uzgodnić z laboratorium.',
cholesterol:'Hiperkolesterolemia z białkomoczem i małą albuminą stanowi inny wzorzec niż wzrost przy cholestazie lub podejrzeniu niedoczynności tarczycy. Mały cholesterol z hipoalbuminemią i objawami jelitowymi wymaga rozważenia strat i wchłaniania, ale także syntezy. Oceniaj triglicerydy osobno: oba wyniki mogą zmieniać się równolegle lub rozbieżnie, ponieważ opisują różne składniki lipoprotein.',
triglycerides:'Potwierdzony wzrost na czczo wymaga analizy diety, chorób endokrynnych, leków i ewentualnych predyspozycji rasowych. Zmiana po posiłku nie jest tym samym co utrwalona hiperlipidemia. Przy podejrzeniu zapalenia trzustki sam poziom triglicerydów nie zastępuje oceny trzustki. Silna lipemia może dodatkowo utrudniać interpretację innych parametrów tej samej próbki.',
ldh:'LDH z innymi markerami uszkodzenia może potwierdzać, że proces komórkowy zachodzi, ale rzadko lokalizuje go bez pomocy. Wysokie LDH przy hemolizie próbki wymaga kontroli przed przypisaniem zmiany narządowi. AST, CK i enzymy wątrobowe pozwalają zawęzić kontekst. Zmiana w izolacji ma zwykle mniejszą wartość niż spójny wzorzec bardziej swoistych parametrów.',
ck:'Wyraźna CK z objawami mięśniowymi uzasadnia ocenę uszkodzenia miocytów, ale możliwy jest uraz wtórny do drgawek, unieruchomienia lub zabiegów. AST może utrzymywać się inaczej niż CK, co pomaga wyjaśnić różnice w kolejnych pomiarach. Jeżeli wzrost się utrzymuje mimo ustania przejściowego bodźca, szersza ocena jest istotniejsza niż sama powtarzana liczba.',
amylase:'Przy wysokiej amylazie z azotemią rozważ wpływ choroby nerek, a nie od razu zapalenie trzustki. Wymioty i ból brzucha wymagają różnicowania wielu chorób niezależnie od wyniku enzymu. Testy trzustkowe dobiera się do problemu: PLI do oceny podejrzenia zapalenia, TLI do niewydolności zewnątrzwydzielniczej. Nie są to zamienne odpowiedniki amylazy.',
lipase:'Interpretacja musi zaczynać się od pełnej nazwy metody, np. testu aktywności albo immunoreaktywności. Dodatni wynik zwiększa lub zmniejsza prawdopodobieństwo w określonym kontekście, ale nie zastępuje objawów i obrazowania. Utrzymujące się dolegliwości przy wyniku w zakresie mogą wymagać dalszej oceny. Sama normalizacja aktywności nie jest pełnym potwierdzeniem ustąpienia choroby.',
fructosamine:'Fruktozamina może pomóc odróżniać utrwaloną hiperglikemię od krótkiej reakcji stresowej, zwłaszcza u kota. Interpretuj ją jednak z albuminą i chorobami wpływającymi na obrót białek. W monitorowaniu średnia może wyglądać korzystnie mimo niebezpiecznych epizodów małej glikemii. Wywiad o pragnieniu, apetycie, masie i objawach hipoglikemii pozostaje niezbędny.',
iron:'Małe żelazo z mikrocytozą i niedobarwliwością zwiększa znaczenie poszukiwania przewlekłej utraty krwi. Małe żelazo przy zapaleniu i bez tych cech może mieć inny mechanizm. Ferrytyna i parametry wiązania także wymagają kontekstu, ponieważ nie wszystkie są odporne na zapalenie. Nie rozpoczynaj rozumowania od założenia, że każdy pacjent z niedokrwistością ma niedobór żelaza.',
copper:'Przy podejrzeniu choroby wątroby związanej z miedzią wynik krwi jest danymi pomocniczymi, nie zastępstwem właściwej oceny narządu. Gromadzenie może być przyczyną lub towarzyszyć innym zmianom; istotne są ilość, rozmieszczenie i obraz tkanki. Oceń dietę i suplementy, ale nie zakładaj, że brak podwyższenia we krwi wyklucza nadmierny zapas wątrobowy.',
zinc:'Przy podejrzeniu zatrucia objawy pokarmowe i hemoliza powinny być zestawione z wywiadem o przedmiotach zawierających cynk i obrazowaniem. Przy problemie dermatologicznym droga interpretacji jest inna: dieta i zaburzenia wykorzystania mogą być ważniejsze niż pojedynczy pomiar. Zanieczyszczenie próbki i wcześniejsza suplementacja mogą zmienić ocenę obu sytuacji.',
"uric-acid":'U pacjenta z kryształami moczanowymi oceń rasę, metabolizm wątrobowy i skład kamienia, zamiast opierać rozpoznanie na surowicy. Zaburzenia wydalania mogą nie odpowiadać proporcjonalnie stężeniu we krwi. Leki wpływające na przemiany puryn dodatkowo zmieniają kontekst. Wartość parametru zależy od konkretnego podejrzenia, a nie tylko obecności w szerokim panelu biochemicznym.',
t3:'T3 należy rozpatrywać jako element osi hormonalnej, nie samodzielny test przesiewowy. Przy niezgodności z T4 i objawami sprawdź choroby ogólne, leczenie i interferencje. U psa ocena podejrzenia niedoczynności opiera się na odpowiednio dobranym profilu i prawdopodobieństwie klinicznym. U kota z podejrzeniem nadczynności poprawne T3 nie kończy diagnostyki.',
t4:'U psa małe T4 wraz z typowymi objawami, małym fT4 i odpowiednią odpowiedzią TSH tworzy inny obraz niż izolowany spadek w ciężkiej chorobie ogólnej. U kota wzrost zgodny z objawami wspiera ocenę nadczynności. W monitorowaniu lewotyroksyny znaczenie ma pobranie względem dawki; wynik pacjenta leczonego nie jest interpretowany identycznie jak wynik przed leczeniem.',
ft3:'Rozbieżność fT3 z innymi hormonami nie powinna automatycznie prowadzić do nowego rozpoznania. Oceń, czy test był uzasadniony i czy metoda jest odpowiednia dla gatunku. Zmiany konwersji obwodowej w chorobie ogólnej mogą zmieniać obraz hormonalny. Wniosek powinien wynikać z pełnego profilu i objawów, a nie ze szczególnej wagi nadanej nazwie „wolny hormon”.',
ft4:'Przy małym fT4 u psa oceń TSH, leki i choroby ogólne. Przy wysokim fT4 u kota bez jednoznacznego T4 lub objawów sprawdź ograniczenia swoistości. Metody oznaczenia mogą reagować odmiennie na białka i przeciwciała. Wyniki uzyskane różnymi technikami wymagają ich własnych zakresów; nie należy przenosić samej liczby między raportami.',
tsh:'Wysokie TSH z małym T4 może wspierać pierwotną niedoczynność, lecz wynik zależy od kontekstu i leczenia. Brak wzrostu TSH jej nie wyklucza. U kota po leczeniu nadczynności trzeba oceniać możliwość niedoczynności jatrogennej łącznie z T4 i stanem klinicznym. Samo dążenie do konkretnego TSH bez pozostałych danych może prowadzić do błędnej oceny.',
cortisol:'Rozróżniaj próbkę podstawową, test stymulacji ACTH i test hamowania deksametazonem. Każdy ma odrębny cel, momenty pobrania i kryteria interpretacji. Choroba ogólna może wpływać na swoistość oceny hiperkortyzolemii. Przy podejrzeniu hipoadrenokortycyzmu glikokortykosteroidy podane przed badaniem mogą zmieniać wynik; historia leków jest częścią interpretacji, nie dodatkiem.',
phenobarbital:'Stężenie oceniaj razem z dzienniczkiem napadów, działaniami niepożądanymi i parametrami wątrobowymi. Wzrost enzymów może mieć różne mechanizmy i nie każdy oznacza niewydolność. Jeżeli wynik nagle się zmienił, sprawdź pominięte dawki, interakcje i termin pobrania. Zakres terapeutyczny jest narzędziem do indywidualnej oceny, a nie automatycznym algorytmem dawkowania.',
insulin:'Para glukoza–insulina musi odpowiadać tej samej sytuacji metabolicznej. Niezahamowana insulina podczas potwierdzonej hipoglikemii ma inne znaczenie niż podobne stężenie po jedzeniu. Wysoki wynik przy dużej glikemii może odzwierciedlać insulinooporność. Uwzględnij preparaty podawane pacjentowi i swoistość testu; sam stosunek liczb nie zastępuje logicznej oceny sprzężenia zwrotnego.',
"estradiol-male":'Przy feminizacji lub podejrzeniu zaburzenia steroidogenezy zestaw wynik z badaniem gonad, objawami skórnymi i morfologią. Istotna jest także ekspozycja na hormony zewnętrzne. Pojedynczy wynik nie potwierdza konkretnego typu guza. Dalsze badania powinny odpowiadać pytaniu o źródło hormonów, zamiast powtarzać sam pomiar bez kontekstu.',
"estradiol-female":'Faza cyklu, kastracja i objawy rujowe zmieniają punkt odniesienia. W podejrzeniu czynnej pozostałości jajnika pojedyncza mała wartość może być niewystarczająca, ponieważ wydzielanie jest zmienne. Zestaw badanie z wywiadem i oceną narządu rozrodczego. Test podstawowy, cytologia i inne markery hormonalne nie są zamienne i odpowiadają na różne pytania.',
"testosterone-male":'Przy poszukiwaniu tkanki jądrowej niski wynik podstawowy nie musi wykluczać jej obecności. Wskazanie do testu stymulacyjnego lub innego markera zależy od sytuacji klinicznej i metody. Przy ocenie płodności stężenie testosteronu jest tylko fragmentem obrazu: anatomia, jakość nasienia i historia rozrodu wnoszą inne niezbędne informacje.',
"testosterone-female":'Przy cechach androgenizacji oceń nie tylko sam wynik, lecz także obraz gonad, nadnerczy i możliwą ekspozycję na preparaty hormonalne. Pojedyncze przekroczenie nie lokalizuje źródła steroidu. Ważne są utrzymywanie się zmiany i współistniejące objawy. Bardzo małe stężenia wymagają metody o odpowiedniej czułości, a nie interpretacji przypadkowego zakresu dla samca.',
pth:'Wysokie PTH przy małym lub odpowiednio ocenionym iCa może być odpowiedzią wtórną, m.in. w zaburzeniach nerkowych i mineralnych. Brak supresji przy wysokim iCa kieruje rozumowanie inaczej. Fosfor i czynność nerek pomagają odróżniać te wzorce. Wyniki z próbek pobranych w odmiennych warunkach mogą nie przedstawiać tej samej odpowiedzi regulacyjnej.',
b12:'Mała B12 z objawami jelitowymi kieruje uwagę na wchłanianie, a z małym TLI także na trzustkę. Samo uzupełnienie niedoboru może poprawiać stan, ale nie usuwa automatycznie jego przyczyny. Wynik po suplementacji ma inne znaczenie niż przed nią. Wysokie stężenie nie jest lustrzanym przeciwieństwem niedoboru i wymaga uwzględnienia podawanych preparatów.',
tli:'Małe TLI z utratą masy i objawami nieprawidłowego trawienia wspiera ocenę EPI, lecz wynik graniczny wymaga aktualnych kryteriów metody. Wysokie TLI może towarzyszyć różnym procesom i nie potwierdza zapalenia. PLI służy innemu celowi. Oceniaj B12, ponieważ jej niedobór może współistnieć z EPI i pogarszać odpowiedź na leczenie.',
usg:'Azotemia z nieadekwatnie małym zagęszczeniem moczu wymaga oceny nerek, ale płyny, leki i choroby pozanerkowe mogą zmieniać odpowiedź. Niskie zagęszczenie bez azotemii również bywa istotne, jeśli utrzymuje się mimo spodziewanej oszczędności wody. Pojedynczy mocz nie mierzy maksymalnej zdolności nerki, a jego gęstość nie jest równoznaczna z osmolalnością.',
upc:'Podwyższone UPC w aktywnym osadzie nie powinno być od razu interpretowane jako izolowana choroba kłębuszków. Po uwzględnieniu przyczyn pozanerkowych ważne jest utrzymywanie się zmiany. Albumina, ciśnienie i markery filtracji uzupełniają ocenę konsekwencji. Pomiar białkomoczu i pomiar filtracji opisują odrębne aspekty nerek, więc poprawny jeden z nich nie unieważnia drugiego.',
ph:'Zasadowy mocz z bakteriami i objawami ma inny kontekst niż zasadowa stara próbka bez spójnych danych klinicznych. Kwaśny odczyn nie wyklucza zakażenia. Typ kryształów, dieta i terapia wpływają na oczekiwaną wartość. Przy podejrzeniu zaburzenia kanalikowego konieczna jest ocena równowagi ustrojowej; sam pasek moczowy jej nie odtwarza.',
"ur-rbc":'Krwiomocz z leukocytami, bakteriami lub kryształami tworzy różne zestawy podejrzeń, lecz sam osad nie zawsze ustala źródło. Krew wprowadzona podczas cystocentezy może wpływać także na ocenę białka. Dodatni hem bez zachowanych RBC skłania do rozważenia lizy lub barwników. Intensywność koloru próbki nie jest precyzyjnym pomiarem liczby krwinek.',
"ur-protein":'Dodatni pasek w silnie zagęszczonym moczu może mieć inne znaczenie niż taki sam wynik w moczu rozcieńczonym. Przy podejrzeniu utraty nerkowej zestaw go z UPC i osadem. Krwawienie i zapalenie mogą zwiększać zawartość białka niezależnie od bariery kłębuszkowej. Utrwalona zmiana jest bardziej użyteczna niż izolowany wynik bez kontekstu.',
"ur-bacteria":'Bakterie z ropomoczem i objawami wspierają podejrzenie zakażenia, ale brak leukocytów nie wyklucza go w każdej sytuacji. Materiał z mikcji wymaga szczególnej oceny kontaminacji. Posiew należy interpretować w powiązaniu ze sposobem pobrania i wcześniejszym leczeniem. Samo „obecne” w osadzie nie podaje lekowrażliwości ani konieczności leczenia.',
"ur-crystals":'Rodzaj kryształu ma większe znaczenie niż samo nasilenie. Próbka schłodzona lub oceniona po czasie może zawierać osad, którego nie było w pęcherzu. Przy dolegliwościach obrazowanie odpowiada na pytanie o kamienie i przeszkodę w odpływie. Zmiana diety powinna wynikać z rozpoznanego problemu, a nie wyłącznie z niezidentyfikowanego kryształu.',
"ur-casts":'Wałeczki komórkowe lub ziarniste mogą wspierać podejrzenie procesu kanalikowego, ale nie wskazują jednej etiologii. Nieliczne szkliste mają inne znaczenie niż liczne komórkowe. Kreatynina i SDMA mogą pozostać w zakresie mimo lokalnego procesu, dlatego brak azotemii nie unieważnia osadu. Zawsze uwzględniaj świeżość i warunki przygotowania próbki.',
creat:'Przy rozbieżności kreatyniny z SDMA i obrazem klinicznym oceń umięśnienie, nawodnienie i wcześniejsze wyniki. Filtracja, utrata białka oraz zdolność zagęszczania są różnymi funkcjami: prawidłowy jeden parametr nie oznacza prawidłowości pozostałych. Chorobę przewlekłą rozpoznaje się z całego obrazu i utrzymywania zmian, a nie z jednego przekroczenia granicy.'
};
for(const [id,text] of Object.entries(analysis))data[id].analysis=text;

add('folate','Foliany uczestniczą w przenoszeniu jednostek jednowęglowych potrzebnych m.in. do syntezy nukleotydów. Oznaczenie w surowicy wykorzystuje się jako pośrednią informację o podaży i wchłanianiu, a nie pomiar każdej puli tkankowej.||Wchłanianie zachodzi w proksymalnej części jelita cienkiego, co odróżnia ten parametr od B12 związanej z dalszym odcinkiem jelita. Choroba nie zawsze jest jednak ograniczona do jednego miejsca. Prawidłowe witaminy nie wykluczają przewlekłej enteropatii.','Foliany w zakresie nie wykluczają choroby jelita. Zmiana może nie być wystarczająco nasilona lub długotrwała, a suplementacja może modyfikować wynik.','Nie rozpoznawaj dysbiozy ani nie dobieraj antybiotyku z wysokiego B9. Leczenie powinno dotyczyć rozpoznanej sytuacji klinicznej.');
data.folate.analysis='Interpretuj foliany razem z B12, objawami jelitowymi, masą ciała i stanem trzustki. Obniżenie wspiera ocenę wchłaniania, ale nie lokalizuje samo konkretnej zmiany histologicznej. Wzrost przy małej B12 nie jest swoistym testem dysbiozy. Uzupełnienie witaminy nie usuwa automatycznie przyczyny enteropatii. Odnotuj wcześniejszą suplementację i porównuj wyniki uzyskane w prawidłowo przygotowanych próbkach.';
add('cpl','Lipaza trzustkowa uczestniczy w trawieniu tłuszczu. Podczas uszkodzenia trzustki może przedostawać się do krwi, gdzie swoisty test immunologiczny wykrywa jej stężenie. To inne podejście niż oznaczanie całej aktywności enzymów zdolnych do rozkładania wybranego substratu.||Swoistość pochodzenia trzustkowego nie oznacza, że każdy pojedynczy wynik rozstrzyga rozpoznanie. Obraz kliniczny, nasilenie i moment procesu wpływają na wartość interpretacyjną. Progi testów ilościowych i wyniki szybkich testów przesiewowych nie są zamienne.','cPL w zakresie zmniejsza podejrzenie, ale nie wyklucza wszystkich przypadków zapalenia, zwłaszcza łagodnego lub nieuchwyconego w danym momencie.','Nie interpretuj cPL jako testu EPI ani skali ciężkości zapalenia. Wybór dalszej oceny zależy od objawów i pozostałych badań.');
data.cpl.analysis='Odróżniaj pytanie o uszkodzenie trzustki od pytania o zdolność do wydzielania enzymów. cPL wspiera ocenę pierwszego, a TLI służy przede wszystkim drugiemu. Rozbieżność między USG a cPL wymaga analizy czasu, metody i prawdopodobieństwa klinicznego. Podobna korelacja dwóch testów lipazy nie czyni ich zamiennymi. Nie przenoś progów Spec cPL na inne oznaczenie aktywności.';
add('fpl','Lipaza trzustkowa jest enzymem trawiennym komórek pęcherzykowych. Test fPL jest przeznaczony dla kota i wykrywa lipazę pochodzenia trzustkowego metodą immunologiczną. Zwykłe oznaczenie aktywności lipazy mierzy inny rodzaj sygnału.||Czułość zależy m.in. od nasilenia procesu. Choroba łagodna lub przewlekła może być trudniejsza do uchwycenia niż wyraźne aktywne zapalenie. Brak typowych objawów nie unieważnia podejrzenia, ale nieswoisty brak apetytu nie powinien być wyjaśniany wyłącznie jednym testem.','fPL w zakresie nie wyklucza każdego zapalenia trzustki. Przy utrzymującym się podejrzeniu ważne są objawy, obrazowanie i ponowna ocena w odpowiednim momencie.','fPL i fTLI odpowiadają na różne pytania. Nie przenoś progów psa na kota i nie utożsamiaj stężenia z ciężkością całej choroby.');
data.fpl.analysis='Wynik fPL zestawiaj z badaniem klinicznym i obrazem trzustki, ale także z jelitami, wątrobą i drogami żółciowymi. Choroby mogą współistnieć; wykrycie jednej nie wyklucza innych. Wynik graniczny nie powinien prowadzić do automatycznego przypisania wszystkich objawów trzustce. Oceniaj również glikemię oraz stan odżywienia. Rutynowa amylaza, lipaza i fPL nie są równoważnymi pomiarami.';

window.LaboratoryReading=data;
})();
